async function api(url,opt={}){
 const headers={"Content-Type":"application/json",...(opt.headers||{})};
 if(authToken)headers.Authorization=`Bearer ${authToken}`;
 const r=await fetch(url,{...opt,headers});
 if(r.status===401){if(url!=="/api/auth/login"){logoutLocal();showLogin("Sua sessão expirou. Entre novamente.")}throw new Error("Sessão expirada.")}
 if(!r.ok){let b={};try{b=await r.json()}catch{};throw new Error([b.error,b.detail].filter(Boolean).join(" — ")||`Erro na operação (HTTP ${r.status}). Consulte os logs do servidor.`);}
 if(r.status===204)return null; return r.json();
}
async function publicApi(url,opt={}){const headers={"Content-Type":"application/json",...(opt.headers||{})};const r=await fetch(url,{...opt,headers});if(!r.ok){let b={};try{b=await r.json()}catch{};throw new Error(b.error||"Não foi possível entrar.")}return r.json()}
const brl=v=>Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
const dmy=v=>v?new Date(v.length===10?v+"T12:00:00":v).toLocaleDateString("pt-BR"):"—";
const esc=v=>String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
function toast(t){const e=$("#toast");if(!e){console.warn("Toast:",t);return}e.textContent=t;e.classList.remove("hidden");setTimeout(()=>e.classList.add("hidden"),2500)}
function badge(s){const labels={quotation:"Em cotação",sent:"Enviado",negotiation:"Negociação",approved:"Aprovado",rejected:"Recusado",pending_payment:"Aguard. pagamento",purchase:"Compra realizada",awaiting_art:"Aguard. layout",art_sent:"Layout enviado",art_approved:"Layout aprovado",production:"Em produção",ready:"Pronto",shipped:"Enviado",delivered:"Entregue",cancelled:"Cancelado",pending:"Pendente",paid:"Pago",overdue:"Vencido",draft:"Rascunho"};const cls=["approved","paid","delivered","ready","art_approved"].includes(s)?"green":["rejected","cancelled","overdue"].includes(s)?"red":"amber";return `<span class="badge ${cls}">${labels[s]||s||"—"}</span>`}
function field(label,name,value="",attrs="",cls=""){return `<div class="field ${cls}"><label>${label}</label><input name="${name}" value="${esc(value)}" ${attrs}></div>`}
function textarea(label,name,value="",cls=""){return `<div class="field ${cls}"><label>${label}</label><textarea name="${name}">${esc(value)}</textarea></div>`}
function select(label,name,value,opts,cls=""){return `<div class="field ${cls}"><label>${label}</label><select name="${name}">${opts.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?"selected":""}>${esc(t)}</option>`).join("")}</select></div>`}
function back(title,subtitle){return `<div class="page-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="btn btn-light" onclick="loadPage('${currentPage}')">← Voltar</button></div>`}
function clientName(id){return cache.clients.find(x=>x.id===Number(id))?.name||cache.clients.find(x=>x.id===Number(id))?.company||"Cliente"}
function supplierName(id){return cache.suppliers.find(x=>x.id===Number(id))?.name||"—"}
function userName(idOrName){const u=cache.users.find(x=>x.id===Number(idOrName));return u?.name||idOrName||"—"}
function isOrderDelivered(o){return Boolean(o&&((o.productionStage||o.status)==='delivered'||o.status==='delivered'))}
function quoteHasDeliveredOrder(q){return cache.orders.some(o=>isOrderDelivered(o)&&(Number(o.quoteId)===Number(q.id)||Number(q.convertedOrderId)===Number(o.id)))}
function clientHasDeliveredOrder(clientId){const id=Number(clientId||0);return Boolean(id&&cache.orders.some(o=>Number(o.clientId)===id&&isOrderDelivered(o)))}

let c4uCacheReady=false, c4uLastRefresh=0, c4uRefreshInFlight=null, c4uRefreshEpoch=0, c4uPageTicket=0;
async function refresh(){
 if(c4uRefreshInFlight)return c4uRefreshInFlight;
 const job=c4uRefreshCollections();c4uRefreshInFlight=job;
 try{return await job}finally{if(c4uRefreshInFlight===job)c4uRefreshInFlight=null}
}
async function c4uRefreshCollections(){
 const epoch=c4uRefreshEpoch;
 try{
  const data=await api('/api/bootstrap');
  if(epoch!==c4uRefreshEpoch)return;
  Object.keys(cache).forEach(x=>{cache[x]=Array.isArray(data[x])?data[x]:[]});
  c4uCacheReady=true; c4uLastRefresh=Date.now();
  updateChatNavBadge().catch(()=>{});
 }catch(e){
  console.warn('C4U: falha ao aquecer o cache:',e.message);
  throw e;
 }
}
async function updateChatNavBadge(){if(!me||!authToken)return;try{const [threads,inbox]=await Promise.all([api('/api/chat/threads'),api('/api/chat/inbox-unread')]),n=threads.reduce((sum,t)=>sum+Number(t.unread||0),0)+Number(inbox.unread||0),b=$('#chatNavBadge');if(b){b.textContent=n>99?'99+':n;b.classList.toggle('hidden',!n)}}catch{}}

const sidebar=$("#sidebar"), mainShell=$("#main"), sidebarToggle=$("#sidebarToggle");
const isMobileLayout=()=>window.matchMedia('(max-width:760px)').matches;
function setMobileMenu(open){
 document.body.classList.toggle('mobile-nav-open',Boolean(open));
 if(sidebarToggle){sidebarToggle.title=open?'Fechar menu':'Abrir menu';sidebarToggle.setAttribute('aria-label',sidebarToggle.title)}
}
function setSidebarCollapsed(collapsed,persist=true){
 if(!sidebar||!mainShell)return;
 if(isMobileLayout()){sidebar.classList.remove('collapsed');mainShell.classList.remove('collapsed');setMobileMenu(Boolean(collapsed));return}
 sidebar.classList.toggle("collapsed",collapsed);
 mainShell.classList.toggle("collapsed",collapsed);
 if(sidebarToggle){sidebarToggle.title=collapsed?"Expandir menu":"Recolher menu";sidebarToggle.setAttribute("aria-label",sidebarToggle.title)}
 if(persist)localStorage.setItem('c4uSidebarV13-user-'+(me?.id||'guest'),collapsed?'1':'0');
}
if(sidebarToggle)sidebarToggle.onclick=()=>isMobileLayout()?setMobileMenu(!document.body.classList.contains('mobile-nav-open')):setSidebarCollapsed(!sidebar?.classList.contains("collapsed"));
if(sidebar&&mainShell)setSidebarCollapsed(localStorage.getItem("c4uSidebarV13")==="1",false);
window.addEventListener('resize',()=>{if(!isMobileLayout())setMobileMenu(false)});
document.addEventListener('click',e=>{if(isMobileLayout()&&document.body.classList.contains('mobile-nav-open')&&!sidebar?.contains(e.target)&&e.target!==sidebarToggle&&!sidebarToggle?.contains(e.target))setMobileMenu(false)});

function applyTheme(theme){
 const t=theme==="dark"?"dark":"light";
 document.documentElement.dataset.theme=t;
 localStorage.setItem('c4uThemeV13-user-'+(me?.id||'guest'),t);
 const b=$("#themeToggle");if(b){b.dataset.mode=t;b.title=t==="light"?"Mudar para tema escuro":"Mudar para tema claro"}
}
applyTheme("light");
const themeToggle=$("#themeToggle");if(themeToggle)themeToggle.onclick=()=>applyTheme(document.documentElement.dataset.theme==="dark"?"light":"dark");

function closeTopPanels(except=''){$$('.top-popover').forEach(p=>{if(p.id!==except)p.classList.add('hidden')})}
function toggleTopPanel(id){const p=$('#'+id);if(!p)return;const willOpen=p.classList.contains('hidden');closeTopPanels(willOpen?id:'');p.classList.toggle('hidden',!willOpen)}
function setupTopbarUser(){const name=me?.name||'Usuário',role=me?.role||'';const n=$('#topProfileName'),r=$('#topProfileRole'),a=$('#topProfileAvatar');if(n)n.textContent=name;if(r)r.textContent=role;if(a){a.textContent=me?.photoData?'':chatInitials(name);a.style.backgroundImage=me?.photoData?'url('+JSON.stringify(me.photoData)+')':'';a.style.backgroundSize='cover';a.style.backgroundPosition='center'}}
function updateTopbarPresence(p){if(!p)return;const online=(p.users||[]).filter(u=>u.online),count=$('#onlineUsersCount'),panel=$('#onlineUsersPanel');if(count)count.textContent=online.length;if(panel)panel.innerHTML=`<div class="top-popover-head"><b>Usuários online</b><small>${online.length} ativo(s) agora</small></div><div class="top-user-list">${online.length?online.map(u=>`<div class="top-user-row"><span class="dash-avatar">${esc(chatInitials(u.name))}</span><span><b>${esc(u.name)}</b><small>${esc(u.role||'Equipe')} • ${esc(({available:'Disponível',busy:'Ocupado',meeting:'Em reunião',away:'Ausente'})[u.availabilityStatus]||'Disponível')}${u.machines?.length?` • ${u.machines.length} máquina(s)`:''}</small></span><i class="presence-dot online"></i></div>`).join(''):'<div class="top-popover-empty">Ninguém online.</div>'}</div>`}
async function refreshTopbarPresence(){try{updateTopbarPresence(await api('/api/presence'))}catch{}}
async function refreshTopbarNotifications(){try{const rows=await api('/api/notifications'),unread=rows.filter(n=>!n.read),badge=$('#topNotificationsBadge'),panel=$('#topNotificationsPanel');if(badge){badge.textContent=unread.length>99?'99+':unread.length;badge.classList.toggle('hidden',!unread.length)}if(panel)panel.innerHTML=`<div class="top-popover-head"><b>Notificações</b><button onclick="loadPage('notifications');closeTopPanels()">Ver todas</button></div><div class="top-notification-list">${rows.slice(0,6).map(n=>`<button onclick="${n.page?`loadPage('${esc(n.page)}');`:''}closeTopPanels()" class="${n.read?'':'unread'}"><i></i><span><b>${esc(n.title||'Notificação')}</b><small>${esc(n.message||'')}</small></span><time>${dashboardTime(n.createdAt)}</time></button>`).join('')||'<div class="top-popover-empty">Sem notificações.</div>'}</div>`}catch{}}
async function refreshTopbar(){setupTopbarUser();await Promise.all([refreshTopbarPresence(),refreshTopbarNotifications()])}
const topNotificationsBtn=$('#topNotificationsBtn');if(topNotificationsBtn)topNotificationsBtn.onclick=async e=>{e.stopPropagation();await refreshTopbarNotifications();toggleTopPanel('topNotificationsPanel')};
