function clearChatImage(){chatDraftFile=null;chatDraftImage=null;chatDraftImageName='';const box=$('#chatImagePreview');if(box){box.innerHTML='';box.classList.add('hidden')}const i=$('#chatFileInput');if(i)i.value=''}
function resizeChatImage(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith('image/'))return reject(new Error('Escolha uma imagem.'));if(file.size>12*1024*1024)return reject(new Error('Imagem muito grande. Escolha uma com até 12 MB.'));const rd=new FileReader();rd.onerror=()=>reject(new Error('Não foi possível ler a imagem.'));rd.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('Imagem inválida.'));img.onload=()=>{const max=1600,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.82))};img.src=rd.result};rd.readAsDataURL(file)})}
async function renderInbox(){try{const [rows,users,unread]=await Promise.all([api(`/api/chat/inbox?folder=${encodeURIComponent(inboxFolder)}`),api('/api/chat/users'),api('/api/chat/inbox-unread')]);window.chatUsers=users;if(inboxActiveId&&!rows.some(x=>x.id===inboxActiveId))inboxActiveId=null;const active=inboxActiveId?await api(`/api/chat/inbox/${inboxActiveId}`):null;content.innerHTML=`${communicationTabs('inbox')}<div class="inbox-page"><div class="inbox-toolbar"><div><h2>Caixa de Entrada</h2><p>Comunicados formais, acordos internos e confirmações de ciência.</p></div><input class="c4u-inbox-search" id="c4uInboxSearch" type="search" placeholder="Buscar nesta pasta..." aria-label="Buscar nesta pasta"><label class="c4u-inbox-filter"><input id="c4uInboxUnread" type="checkbox"> Não lidas</label><button class="btn btn-primary" onclick="openInboxCompose()">+ Nova comunicação</button></div><div class="inbox-shell card"><aside class="inbox-folders">${inboxFolderButton('received','📥','Recebidos',unread.unread)}${inboxFolderButton('sent','📤','Enviados',0)}${inboxFolderButton('important','★','Importantes',0)}${inboxFolderButton('archived','▣','Arquivados',0)}</aside><section class="inbox-list"><div class="inbox-list-head"><b>${({received:'Recebidos',sent:'Enviados',important:'Importantes',archived:'Arquivados'})[inboxFolder]}</b><span>${rows.length} ${rows.length===1?'registro':'registros'}</span></div><div class="inbox-items">${rows.length?rows.map(inboxRowHtml).join(''):'<div class="inbox-empty">Nenhuma comunicação nesta pasta.</div>'}</div></section><section class="inbox-reader">${active?inboxReaderHtml(active):inboxReaderEmpty()}</section></div></div>`;const b=$('#inboxTabBadge');if(b&&unread.unread){b.textContent=unread.unread>99?'99+':unread.unread;b.classList.add('has-value')}updateChatNavBadge().catch(()=>{});c4uBindInboxFilter()}catch(e){content.innerHTML=`${communicationTabs('inbox')}<div class="card empty">Não foi possível carregar a Caixa de Entrada.<br><small>${esc(e.message)}</small></div>`}}
function inboxFolderButton(key,icon,label,count){return `<button class="${inboxFolder===key?'active':''}" onclick="inboxFolder='${key}';inboxActiveId=null;renderInbox()"><i>${icon}</i><span>${label}</span>${count?`<em>${count}</em>`:''}</button>`}
function inboxRowHtml(x){const received=(x.recipientIds||[]).map(Number).includes(me?.id),unread=received&&!x.myState?.readAt;return `<button class="inbox-row ${inboxActiveId===x.id?'active':''} ${unread?'unread':''}" onclick="openInboxMessage(${x.id})"><div class="inbox-row-top"><strong>${esc(inboxFolder==='sent'?'Para: '+(x.recipients||[]).map(r=>r.name).join(', '):x.sender?.name||x.senderName||'Usuário')}</strong><time>${chatTime(x.createdAt)}</time></div><b>${esc(x.subject)}</b><small>${esc(x.message||'Imagem anexada')}</small><div class="inbox-row-tags"><span>${esc(x.category||'Comunicado')}</span>${x.priority&&x.priority!=='Normal'?`<span class="priority ${esc(x.priority.toLowerCase())}">${esc(x.priority)}</span>`:''}${x.requireAck?'<span>Requer ciência</span>':''}</div></button>`}
function inboxReaderEmpty(){return `<div class="inbox-reader-empty"><div>✉</div><h3>Comunicação formal</h3><p>Selecione um item ou crie uma nova comunicação.</p></div>`}
function inboxRelatedHtml(x){if(!x.relatedType||!x.relatedId)return '';const map={client:['Cliente','clients'],quote:['Orçamento','quotes'],order:['Pedido','orders']},m=map[x.relatedType];if(!m)return '';const arr=cache[m[1]]||[],r=arr.find(z=>z.id===Number(x.relatedId)),label=r?(r.number||r.name||r.company||`#${r.id}`):`#${x.relatedId}`;return `<div class="inbox-related"><span>Vinculado a <b>${m[0]} ${esc(label)}</b></span><button class="btn btn-light" onclick="loadPage('${m[1]}')">Abrir área</button></div>`}
function replyInbox(x){openInboxCompose({subject:(/^RE:/i.test(x.subject)?x.subject:`RE: ${x.subject}`),category:x.category||'Comunicado',message:'',recipientIds:[Number(x.senderId)],requireAck:false,relatedType:x.relatedType||'',relatedId:Number(x.relatedId||0)})}
function inboxReaderHtml(x){const received=(x.recipientIds||[]).map(Number).includes(me?.id),mine=Number(x.senderId)===Number(me?.id),state=x.myState||{};return `<article class="inbox-message"><header><div><span class="inbox-category">${esc(x.category||'Comunicado')}</span><h2>${esc(x.subject)}</h2><p><b>De:</b> ${esc(x.sender?.name||x.senderName||'Usuário')} &nbsp; <b>Para:</b> ${esc((x.recipients||[]).map(r=>r.name).join(', '))}</p></div><time>${dmy(x.createdAt)} • ${chatTime(x.createdAt)}</time></header>${x.priority&&x.priority!=='Normal'?`<div class="inbox-priority-banner ${esc(x.priority.toLowerCase())}">Prioridade ${esc(x.priority)}</div>`:''}<div class="inbox-message-body">${esc(x.message||'').replace(/\n/g,'<br>')}</div>${inboxRelatedHtml(x)}${x.imageData?`<a class="inbox-attachment" href="${x.imageData}" target="_blank"><img src="${x.imageData}" alt="${esc(x.imageName||'Imagem')}"><span><b>${esc(x.imageName||'Imagem')}</b><small>Abrir anexo</small></span></a>`:''}${mine?inboxStatusHtml(x):''}<footer><div>${x.requireAck?'<span class="inbox-requires">✓ Confirmação de ciência solicitada</span>':''}</div><div>${received?`<button class="btn btn-light" onclick='replyInbox(${JSON.stringify(x)})'>↩ Responder</button>`:''}<button class="btn btn-light" onclick="toggleInboxState(${x.id},'important',${!state.important})">${state.important?'★ Importante':'☆ Marcar importante'}</button>${received&&!state.archived?`<button class="btn btn-light" onclick="toggleInboxState(${x.id},'archived',true)">Arquivar</button>`:''}${received&&x.requireAck&&!state.ackAt?`<button class="btn btn-primary" onclick="ackInbox(${x.id})">Confirmar ciência</button>`:''}${received&&state.ackAt?`<span class="inbox-acked">✓ Ciência confirmada ${chatTime(state.ackAt)}</span>`:''}</div></footer></article>`}
function inboxStatusHtml(x){return `<div class="inbox-status-panel"><h4>Acompanhamento</h4>${(x.recipients||[]).map(r=>{const st=(x.recipientState||{})[String(r.id)]||{};return `<div><b>${esc(r.name)}</b><span>${st.readAt?`Lido ${dmy(st.readAt)} ${chatTime(st.readAt)}`:'Não lido'}${x.requireAck?' • '+(st.ackAt?`Ciência ${dmy(st.ackAt)} ${chatTime(st.ackAt)}`:'Aguardando ciência'):''}</span></div>`}).join('')}</div>`}
async function openInboxMessage(id){inboxActiveId=Number(id);await renderInbox()}
async function ackInbox(id){try{await api(`/api/chat/inbox/${id}/ack`,{method:'POST',body:'{}'});toast('Ciência confirmada.');await renderInbox()}catch(e){toast(e.message)}}
async function toggleInboxState(id,key,value){try{await api(`/api/chat/inbox/${id}/state`,{method:'POST',body:JSON.stringify({[key]:value})});if(key==='archived')inboxActiveId=null;await renderInbox()}catch(e){toast(e.message)}}
function openInboxCompose(prefill={}){const users=(window.chatUsers||cache.users||[]).filter(u=>u.id!==me?.id&&u.active!==false),ov=document.createElement('div');ov.className='modal-overlay';ov.id='inboxComposeModal';ov.innerHTML=`<div class="modal-card inbox-compose-modal"><div class="page-head"><div><h2>Nova comunicação</h2><p>Registre acordos, solicitações e comunicados internos.</p></div><button class="btn btn-light" onclick="document.getElementById('inboxComposeModal').remove()">×</button></div><form id="inboxComposeForm" class="form"><div class="inbox-compose-grid">${field('Assunto *','subject',prefill.subject||'','required maxlength="180"')}${select('Categoria','category',prefill.category||'Acordo',[['Acordo','Acordo'],['Comunicado','Comunicado'],['Solicitação','Solicitação'],['Financeiro','Financeiro'],['Produção','Produção'],['Comercial','Comercial']])}${select('Prioridade','priority','Normal',[['Normal','Normal'],['Alta','Alta'],['Urgente','Urgente']])}</div><div class="field"><label>Vincular a um registro <small>(opcional)</small></label><select name="related"><option value="">Nenhum vínculo</option>${(cache.clients||[]).map(x=>`<option value="client:${x.id}" ${prefill.relatedType==='client'&&Number(prefill.relatedId)===x.id?'selected':''}>Cliente • ${esc(x.name||x.company||'#'+x.id)}</option>`).join('')}${(cache.quotes||[]).map(x=>`<option value="quote:${x.id}" ${prefill.relatedType==='quote'&&Number(prefill.relatedId)===x.id?'selected':''}>Orçamento • ${esc(x.number||'#'+x.id)}</option>`).join('')}${(cache.orders||[]).map(x=>`<option value="order:${x.id}" ${prefill.relatedType==='order'&&Number(prefill.relatedId)===x.id?'selected':''}>Pedido • ${esc(x.number||'#'+x.id)}</option>`).join('')}</select></div><div class="field"><label>Destinatários *</label><div class="inbox-recipient-picker">${users.map(u=>`<label><input type="checkbox" name="recipient" value="${u.id}" ${prefill.recipientIds?.includes(u.id)?'checked':''}><span class="chat-avatar">${esc(chatInitials(u.name))}</span><span><b>${esc(u.name)}</b><small>${esc(u.role||'Equipe')} • ${esc(u.login||u.email||'')}</small></span></label>`).join('')||'<div class="empty">Nenhum outro usuário ativo.</div>'}</div></div>${textarea('Mensagem *','message',prefill.message||'','span-2')}<label class="check-field inbox-ack-check"><input type="checkbox" name="requireAck" ${prefill.requireAck?'checked':''}><span><b>Exigir confirmação de ciência</b><small>O destinatário precisará confirmar que leu e tomou ciência.</small></span></label><div class="inbox-image-field"><label class="btn btn-light">▧ Anexar imagem<input id="inboxImageInput" type="file" accept="image/png,image/jpeg,image/webp" hidden></label><div id="inboxImagePreview"></div></div><input type="hidden" name="sourceChatMessageId" value="${Number(prefill.sourceChatMessageId||0)}"><input type="hidden" name="sourceThreadId" value="${Number(prefill.sourceThreadId||0)}"><div class="form-actions"><button class="btn btn-primary">Enviar comunicação</button></div></form></div>`;document.body.appendChild(ov);inboxDraftImage=prefill.imageData||null;inboxDraftImageName=prefill.imageName||'';if(inboxDraftImage)$('#inboxImagePreview').innerHTML=`<img src="${inboxDraftImage}"><span>${esc(inboxDraftImageName||'Imagem')}</span>`;const imageInput=$('#inboxImageInput');imageInput.onchange=async()=>{const f=imageInput.files?.[0];if(!f)return;try{inboxDraftImage=await resizeChatImage(f);inboxDraftImageName=f.name;$('#inboxImagePreview').innerHTML=`<img src="${inboxDraftImage}"><span>${esc(f.name)}</span>`}catch(e){toast(e.message)}};$('#inboxComposeForm').onsubmit=async e=>{e.preventDefault();const f=e.target,recipientIds=$$('input[name="recipient"]:checked',f).map(x=>Number(x.value)),related=String(f.elements.related?.value||'').split(':');try{await api('/api/chat/inbox',{method:'POST',body:JSON.stringify({relatedType:related[0]||'',relatedId:Number(related[1]||0),subject:f.elements.subject.value,category:f.elements.category.value,priority:f.elements.priority.value,recipientIds,message:f.elements.message.value,requireAck:f.elements.requireAck.checked,imageData:inboxDraftImage||'',imageName:inboxDraftImageName||'',sourceChatMessageId:Number(f.elements.sourceChatMessageId.value||0),sourceThreadId:Number(f.elements.sourceThreadId.value||0)})});ov.remove();inboxDraftImage=null;inboxDraftImageName='';chatMode='inbox';inboxFolder='sent';toast('Comunicação enviada.');await renderInbox()}catch(ex){toast(ex.message)}}}
async function formalizeChatMessage(messageId){try{const threads=await api('/api/chat/threads'),t=threads.find(x=>x.id===chatActiveThreadId);if(!t)return;const msgs=await api(`/api/chat/threads/${t.id}/messages`),m=msgs.find(x=>x.id===Number(messageId));if(!m)return;openInboxCompose({subject:`Formalização — ${chatThreadName(t)}`,category:'Acordo',message:m.text||'',recipientIds:(t.memberIds||[]).map(Number).filter(id=>id!==me?.id),requireAck:true,imageData:m.imageData||'',imageName:m.imageName||'',sourceChatMessageId:m.id,sourceThreadId:t.id})}catch(e){toast(e.message)}}


// ===== C4U v16.0.5 — mapas mentais (UI isolada do chat, com persistência no backend) =====
let mindMapDraft=null,mindMapSelectedId='',mindMapSaving=false;
async function renderMindMaps(){
 mindMapDraft=null;try{const maps=await api('/api/mindmaps');content.innerHTML=`<section class="mindmaps-v1605"><div class="mind-list-head"><div><span class="mind-eyebrow">ESPAÇO DE IDEIAS</span><h2>Mapas mentais</h2><p>Organize ideias e compartilhe mapas com suas conversas.</p></div><button class="btn btn-primary" onclick="createMindMap()">+ Criar mapa</button></div><div class="mind-library">${maps.map(m=>`<article class="mind-list-card"><div class="mind-list-symbol">◇</div><div><h3>${esc(m.title)}</h3><small>${m.nodeCount} blocos · ${m.ownerId===me.id?'Criado por você':((m.editUserIds||[]).includes(me.id)?'Colaborador com edição':'Compartilhado para leitura')} · ${dmy(m.updatedAt)}</small></div><div class="mind-card-actions"><button class="btn btn-light" onclick="openMindMap(${m.id})">Abrir</button><button class="btn btn-light" onclick="c4uToggleFavorite('map',${m.id})">☆ Favoritar</button>${m.ownerId===me.id?`<button class="btn btn-light" onclick="shareMindMap(${m.id})">Compartilhar</button><button class="btn btn-danger btn-sm" onclick="deleteMindMap(${m.id})">Excluir</button>`:''}</div></article>`).join('')||'<div class="card empty">Nenhum mapa ainda. Crie seu primeiro mapa mental.</div>'}</div></section>`}catch(e){content.innerHTML=`<div class="card empty">Não foi possível carregar os mapas. ${esc(e.message)}</div>`}
}
function createMindMap(){
 const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='c4uNewMapModal';
 overlay.innerHTML=`<div class="modal-card c4u-map-create-dialog" role="dialog" aria-modal="true" aria-labelledby="c4uNewMapTitle"><div class="page-head"><div><h2 id="c4uNewMapTitle">Criar mapa mental</h2><p>Comece organizando suas ideias.</p></div><button type="button" class="btn btn-light" id="c4uCloseMapDialog" aria-label="Fechar">×</button></div><form id="c4uNewMapForm" class="form"><div class="field"><label for="c4uNewMapName">Nome do mapa</label><input id="c4uNewMapName" name="title" maxlength="120" placeholder="Ex.: Planejamento da campanha" required autocomplete="off"></div><div class="form-actions"><button type="button" class="btn btn-light" id="c4uCancelMapDialog">Cancelar</button><button type="submit" class="btn btn-primary">Criar mapa</button></div></form></div>`;
 document.body.appendChild(overlay);
 const close=()=>overlay.remove();
 $('#c4uCloseMapDialog',overlay).onclick=close;$('#c4uCancelMapDialog',overlay).onclick=close;
 overlay.addEventListener('click',e=>{if(e.target===overlay)close()});
 $('#c4uNewMapForm',overlay).onsubmit=async e=>{e.preventDefault();const title=$('#c4uNewMapName',overlay).value.trim();if(!title)return;const btn=e.submitter;if(btn)btn.disabled=true;try{const map=await api('/api/mindmaps',{method:'POST',body:JSON.stringify({title})});close();await openMindMap(map.id)}catch(err){toast(err.message);if(btn)btn.disabled=false}};
 $('#c4uNewMapName',overlay).focus();
}
async function deleteMindMap(id){if(!await C4UDialog.confirm('Excluir este mapa? Mensagens já compartilhadas continuarão no histórico, mas o link para este mapa deixará de abrir.'))return;try{await api('/api/mindmaps/'+Number(id),{method:'DELETE'});toast('Mapa excluído');renderMindMaps()}catch(e){toast(e.message)}}
async function openMindMap(id){try{const map=await api('/api/mindmaps/'+Number(id));mindMapDraft=structuredClone(map);mindMapDraft.edges=Array.isArray(mindMapDraft.edges)?mindMapDraft.edges:[];mindMapSelectedId=map.nodes?.[0]?.id||'';renderMindMapEditor()}catch(e){toast(e.message)}}
function mindMapEditable(){return mindMapDraft&&(Number(mindMapDraft.ownerId)===Number(me?.id)||(mindMapDraft.editUserIds||[]).map(Number).includes(Number(me?.id)))}
function mindMapNode(id){return (mindMapDraft?.nodes||[]).find(n=>n.id===id)}
function mindMapDimensions(n){return {w:Number(n?.width)||178,h:Number(n?.height)||90}}
function mindMapLine(a,b){
 const aw=mindMapDimensions(a),bw=mindMapDimensions(b),ax=a.x+aw.w/2,ay=a.y+aw.h/2,bx=b.x+bw.w/2,by=b.y+bw.h/2;
 // Pick a sensible attachment side for left/right or up/down layouts.
 let x1,y1,x2,y2,c1x,c1y,c2x,c2y;
 if(Math.abs(bx-ax)>=Math.abs(by-ay)){
  const dir=bx>=ax?1:-1;x1=ax+dir*aw.w/2;y1=ay;x2=bx-dir*bw.w/2;y2=by;
  c1x=x1+dir*Math.max(35,Math.abs(x2-x1)*.4);c1y=y1;c2x=x2-dir*Math.max(35,Math.abs(x2-x1)*.4);c2y=y2;
 }else{
  const dir=by>=ay?1:-1;x1=ax;y1=ay+dir*aw.h/2;x2=bx;y2=by-dir*bw.h/2;
  c1x=x1;c1y=y1+dir*Math.max(35,Math.abs(y2-y1)*.4);c2x=x2;c2y=y2-dir*Math.max(35,Math.abs(y2-y1)*.4);
 }
 return `M${x1} ${y1} C${c1x} ${c1y},${c2x} ${c2y},${x2} ${y2}`;
}
function mindMapConnections(){
 if(!mindMapDraft)return '';
 const tree=mindMapDraft.nodes.filter(n=>n.parentId&&mindMapNode(n.parentId)).map(n=>`<path d="${mindMapLine(mindMapNode(n.parentId),n)}" fill="none" stroke="#ad91e9" stroke-width="2.5"/>`).join('');
 const extras=(mindMapDraft.edges||[]).filter(e=>mindMapNode(e.from)&&mindMapNode(e.to)).map(e=>{
  const a=mindMapNode(e.from),b=mindMapNode(e.to),aw=mindMapDimensions(a),bw=mindMapDimensions(b),mx=(a.x+aw.w/2+b.x+bw.w/2)/2,my=(a.y+aw.h/2+b.y+bw.h/2)/2;
  return `<path d="${mindMapLine(a,b)}" fill="none" stroke="#377dca" stroke-width="3" stroke-dasharray="8 5" marker-end="url(#c4uMindArrow)"/>${e.label?`<text x="${mx}" y="${my-8}" fill="#285b96" font-size="12" text-anchor="middle">${esc(e.label)}</text>`:''}`;
 }).join('');
 return `<defs><marker id="c4uMindArrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6Z" fill="#377dca"/></marker></defs>${tree}${extras}`;
}
function renderMindMapEditor(){
 const m=mindMapDraft;if(!m)return renderMindMaps();const writable=mindMapEditable(),current=mindMapNode(mindMapSelectedId);
 const selectedLinks=(m.edges||[]).filter(e=>e.from===mindMapSelectedId||e.to===mindMapSelectedId);
 content.innerHTML=`<section class="mindmaps-v1605 mind-editor c4u-mind-pro"><header class="mind-editor-header"><button type="button" class="btn btn-light" onclick="mindMapDraft=null;renderMindMaps()">← Meus mapas</button><div class="mind-editor-name"><span class="mind-eyebrow">MAPA MENTAL · ${writable?'EDITÁVEL':'VISUALIZAÇÃO'}</span><input id="mindTitle" aria-label="Título do mapa" value="${esc(m.title)}" maxlength="120" ${writable?'':'readonly'}></div><div class="mind-editor-actions">${writable?'<button class="btn btn-primary" id="mindSave" onclick="saveMindMap()">Salvar mapa</button>':''}<button class="btn btn-light" onclick="exportMindMap(false)">Exportar SVG</button><button class="btn btn-light" onclick="exportMindMap(true)">Imprimir / PDF</button>${writable?`<button class="btn btn-light" onclick="shareMindMap(${m.id})">Compartilhar no chat</button>`:''}</div></header><p class="c4u-mind-help">Selecione ou arraste blocos. Ajuste tamanho e formato no painel; conecte livremente blocos de diferentes ramos. As notas aparecem dentro de cada ideia. Clique em <b>Salvar mapa</b> para persistir.</p><div class="mind-editor-layout"><div class="mind-canvas-scroll"><div class="mind-canvas" id="mindCanvas"><svg class="mind-wires" viewBox="0 0 3200 2000" aria-hidden="true">${mindMapConnections()}</svg>${m.nodes.map(n=>{const dims=mindMapDimensions(n);return `<button type="button" data-node-id="${esc(n.id)}" class="mind-node c4u-mind-shape-${esc(n.shape||'rounded')} ${n.id===mindMapSelectedId?'selected':''}" style="left:${n.x}px;top:${n.y}px;width:${dims.w}px;height:${dims.h}px;--node-bg:${esc(n.color)}" onclick="selectMindMapNode('${esc(n.id)}')"><small>${n.parentId?'TÓPICO':'IDEIA CENTRAL'}</small><b>${esc(n.label)}</b>${n.notes?`<span class="c4u-mind-node-notes">${esc(n.notes)}</span>`:''}${n.status==='done'?'<em class="mind-node-done">✓</em>':''}</button>`}).join('')}</div></div><aside class="mind-inspector"><h3>Ideia selecionada</h3>${current?`<label>Texto<textarea id="mindNodeLabel" maxlength="180" ${writable?'':'readonly'}>${esc(current.label)}</textarea></label><label>Notas abaixo da ideia<textarea id="mindNodeNotes" maxlength="1500" placeholder="Escreva anotações, detalhes ou próximos passos..." ${writable?'':'readonly'}>${esc(current.notes||'')}</textarea></label><label>Cor<input type="color" id="mindNodeColor" value="${esc(current.color||'#eee6ff')}" ${writable?'':'disabled'}></label><label>Formato<select id="mindNodeShape" ${writable?'':'disabled'}>${[['rounded','Arredondado'],['rectangle','Retangular'],['pill','Cápsula'],['note','Nota adesiva']].map(([v,t])=>`<option value="${v}" ${(current.shape||'rounded')===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="c4u-mind-dimension"><label>Largura (px)<input id="mindNodeWidth" type="number" min="140" max="420" step="10" value="${mindMapDimensions(current).w}" ${writable?'':'disabled'}></label><label>Altura (px)<input id="mindNodeHeight" type="number" min="80" max="260" step="10" value="${mindMapDimensions(current).h}" ${writable?'':'disabled'}></label></div><label>Etapa<select id="mindNodeStatus" ${writable?'':'disabled'}>${[['idea','Ideia'],['doing','Em andamento'],['done','Concluído']].map(([v,t])=>`<option value="${v}" ${v===(current.status||'idea')?'selected':''}>${t}</option>`).join('')}</select></label><label>Prazo<input type="date" id="mindNodeDue" value="${esc(current.dueDate||'')}" ${writable?'':'disabled'}></label>${writable?`<button class="btn btn-primary" onclick="updateMindMapNode()">Aplicar alterações</button><button class="btn btn-light" onclick="addMindMapNode()">+ Subtópico</button><button class="btn btn-danger" onclick="removeMindMapNode()" ${current.parentId?'':'disabled'}>Excluir bloco</button>`:''}<hr><h3>Conexões livres</h3><p>Relacione esta ideia com outros tópicos, inclusive de outros ramos.</p>${writable?`<label>Interligar com<select id="mindConnectTarget"><option value="">Escolher outro bloco...</option>${m.nodes.filter(n=>n.id!==current.id).map(n=>`<option value="${esc(n.id)}">${esc(n.label)}</option>`).join('')}</select></label><button class="btn btn-light" onclick="mindMapLinkNodes()">+ Criar conexão</button>`:''}<div class="c4u-mind-links">${selectedLinks.map(e=>{const other=mindMapNode(e.from===current.id?e.to:e.from);return `<div class="c4u-mind-link"><span>↔ ${esc(other?.label||'Ideia')} ${e.label?'· '+esc(e.label):''}</span>${writable?`<button type="button" data-mind-unlink="${esc(e.id)}">×</button>`:''}</div>`}).join('')||'<small>Sem ligações adicionais.</small>'}</div>`:'Selecione um bloco.'}<hr><small>${m.nodes.length}/160 blocos · ${(m.edges||[]).length} ligações livres</small>${!writable?'<p>Mapa compartilhado para leitura.</p>':''}<hr><div class="c4u-mind-comments"><h3>Comentários da equipe</h3><div id="c4uMindCommentList">Carregando...</div><form id="c4uMindCommentForm"><textarea id="c4uMindCommentText" maxlength="1200" placeholder="Comentar o mapa ou o bloco selecionado..." required></textarea><button class="btn btn-light">Enviar comentário</button></form></div></aside></div></section>`;
 if(writable){bindMindMapDrag();$$('[data-mind-unlink]').forEach(btn=>btn.onclick=()=>mindMapUnlink(btn.dataset.mindUnlink));}
 c4uBindMindComments();
}
function captureMindMapTitle(){const input=$('#mindTitle');if(input&&mindMapEditable())mindMapDraft.title=input.value.trim()||mindMapDraft.title}
function captureMindMapInspector(){
 if(!mindMapEditable())return true;
 const node=mindMapNode(mindMapSelectedId),label=$('#mindNodeLabel');if(!node||!label)return true;
 if(!label.value.trim()){toast('Informe o texto do bloco.');return false}
 node.label=label.value.trim().slice(0,180);node.notes=($('#mindNodeNotes')?.value||'').slice(0,1500);
 node.color=$('#mindNodeColor')?.value||'#eee6ff';node.status=$('#mindNodeStatus')?.value||'idea';node.dueDate=$('#mindNodeDue')?.value||'';
 node.shape=$('#mindNodeShape')?.value||'rounded';node.width=Math.min(420,Math.max(140,Number($('#mindNodeWidth')?.value)||178));node.height=Math.min(260,Math.max(80,Number($('#mindNodeHeight')?.value)||90));
 node.x=Math.min(node.x,3200-node.width);node.y=Math.min(node.y,2000-node.height);
 return true;
}
function selectMindMapNode(id){if(!captureMindMapInspector())return;captureMindMapTitle();mindMapSelectedId=id;renderMindMapEditor()}
function updateMindMapNode(){if(!captureMindMapInspector())return;captureMindMapTitle();renderMindMapEditor()}
function addMindMapNode(){if(!captureMindMapInspector())return;captureMindMapTitle();const n=mindMapNode(mindMapSelectedId);if(!n||!mindMapEditable())return;if(mindMapDraft.nodes.length>=160)return toast('Limite de 160 blocos.');const label='Nova ideia';const id='n'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);const siblings=mindMapDraft.nodes.filter(x=>x.parentId===n.id).length;mindMapDraft.nodes.push({id,label:label.trim().slice(0,180),parentId:n.id,color:'#f0eaff',shape:'rounded',width:190,height:100,notes:'',x:Math.min(3010,n.x+Math.max(225,mindMapDimensions(n).w+45)),y:Math.min(1900,n.y+siblings*115)});mindMapSelectedId=id;renderMindMapEditor()}
async function removeMindMapNode(){if(!captureMindMapInspector())return;captureMindMapTitle();const n=mindMapNode(mindMapSelectedId);if(!n?.parentId||!mindMapEditable())return;if(!await C4UDialog.confirm('Excluir bloco? Os subtópicos serão conectados ao tópico anterior e suas ligações livres serão removidas.'))return;mindMapDraft.nodes.forEach(x=>{if(x.parentId===n.id)x.parentId=n.parentId});mindMapDraft.nodes=mindMapDraft.nodes.filter(x=>x.id!==n.id);mindMapDraft.edges=(mindMapDraft.edges||[]).filter(e=>e.from!==n.id&&e.to!==n.id);mindMapSelectedId=n.parentId;renderMindMapEditor()}
async function mindMapLinkNodes(){
 if(!mindMapEditable()||!captureMindMapInspector())return;captureMindMapTitle();
 const from=mindMapSelectedId,to=$('#mindConnectTarget')?.value;if(!to||from===to)return toast('Selecione outra ideia para conectar.');
 if(mindMapDraft.edges.length>=320)return toast('Limite de 320 conexões adicionais.');
 if((mindMapDraft.edges||[]).some(e=>(e.from===from&&e.to===to)||(e.from===to&&e.to===from)))return toast('Estes blocos já estão conectados.');
 const a=mindMapNode(from),b=mindMapNode(to);if(b.parentId===from||a.parentId===to)return toast('Esses blocos já estão ligados pela hierarquia.');
 const label=await C4UDialog.ask('Rótulo da ligação (opcional):','');if(label===null)return;
 mindMapDraft.edges.push({id:'e'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),from,to,label:label.trim().slice(0,90)});
 renderMindMapEditor();toast('Conexão criada. Clique em Salvar mapa para guardar.');
}
function mindMapUnlink(id){if(!mindMapEditable()||!captureMindMapInspector())return;captureMindMapTitle();mindMapDraft.edges=mindMapDraft.edges.filter(e=>e.id!==id);renderMindMapEditor()}
function bindMindMapDrag(){const canvas=$('#mindCanvas');if(!canvas)return;$$('.mind-node',canvas).forEach(el=>{el.addEventListener('pointerdown',e=>{if(e.button!==0)return;const n=mindMapNode(el.dataset.nodeId);if(!n)return;const origin={x:e.clientX,y:e.clientY,nx:n.x,ny:n.y};let moved=false;el.setPointerCapture(e.pointerId);const drag=ev=>{const dx=ev.clientX-origin.x,dy=ev.clientY-origin.y;if(Math.abs(dx)+Math.abs(dy)>4)moved=true;const dims=mindMapDimensions(n);n.x=Math.min(3200-dims.w,Math.max(0,Math.round(origin.nx+dx)));n.y=Math.min(2000-dims.h,Math.max(0,Math.round(origin.ny+dy)));el.style.left=n.x+'px';el.style.top=n.y+'px';const wires=$('.mind-wires');if(wires)wires.innerHTML=mindMapConnections()};const end=()=>{el.removeEventListener('pointermove',drag);el.removeEventListener('pointerup',end);el.removeEventListener('pointercancel',end);if(moved){mindMapSelectedId=n.id;$$('.mind-node',canvas).forEach(x=>x.classList.toggle('selected',x.dataset.nodeId===n.id));toast('Posição alterada. Clique em Salvar mapa para guardar.')}};el.addEventListener('pointermove',drag);el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end)})})}
async function saveMindMap(){if(!mindMapEditable()||mindMapSaving)return false;if(!captureMindMapInspector())return false;const title=$('#mindTitle')?.value.trim();if(!title){toast('Informe o título do mapa.');return false}mindMapDraft.title=title;mindMapSaving=true;const btn=$('#mindSave');if(btn)btn.disabled=true;try{mindMapDraft=await api('/api/mindmaps/'+mindMapDraft.id,{method:'PUT',body:JSON.stringify({title:mindMapDraft.title,nodes:mindMapDraft.nodes,edges:mindMapDraft.edges||[],revision:mindMapDraft.revision||1})});mindMapDraft.edges=mindMapDraft.edges||[];toast('Mapa salvo.');return true}catch(e){toast('Não foi possível salvar: '+e.message);return false}finally{mindMapSaving=false;if(btn)btn.disabled=false}}
async function shareMindMap(id){try{if($('#mindTitle')&&mindMapDraft?.id===Number(id)&&mindMapEditable()&&!await saveMindMap())return;const map=await api('/api/mindmaps/'+Number(id));if(map.ownerId!==me.id)return toast('Somente o criador pode compartilhar.');const threads=await api('/api/chat/threads'),overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='mindShareModal';overlay.innerHTML=`<div class="modal-card"><div class="page-head"><div><h2>Compartilhar mapa</h2><p>${esc(map.title)} — escolher uma conversa</p></div><button class="btn btn-light" onclick="document.getElementById('mindShareModal').remove()">×</button></div><label class="c4u-share-permission">Permissão dos participantes <select id="c4uMindSharePermission"><option value="read">Somente visualizar</option><option value="edit">Visualizar e editar</option></select></label><div class="mind-share-list">${threads.map(t=>`<button class="btn btn-light" onclick="shareMindMapToChat(${map.id},${t.id})">${esc(chatThreadName(t))} →</button>`).join('')||'<p>Crie primeiro uma conversa no Chat.</p>'}</div><p class="mind-share-note">Escolha se os participantes atuais poderão apenas visualizar ou também editar. Alterações simultâneas geram aviso de conflito.</p></div>`;document.body.appendChild(overlay)}catch(e){toast(e.message)}}
async function shareMindMapToChat(id,threadId){try{await api('/api/mindmaps/'+id+'/share',{method:'POST',body:JSON.stringify({threadId,permission:$('#c4uMindSharePermission')?.value||'read'})});$('#mindShareModal')?.remove();chatActiveThreadId=threadId;chatMode='conversations';mindMapDraft=null;toast('Mapa enviado e compartilhado.');loadPage('chat')}catch(e){toast(e.message)}}
function mindMapSVG(){
 const map=mindMapDraft;if(!map)return '';
 const edges=mindMapConnections();
 const nodes=map.nodes.map(n=>{
  const {w,h}=mindMapDimensions(n),shape=n.shape||'rounded',rx=shape==='rectangle'||shape==='note'?3:shape==='pill'?Math.min(w,h)/2:15;
  const rect=`<rect x="${n.x}" y="${n.y}" width="${w}" height="${h}" rx="${rx}" fill="${esc(n.color)}" stroke="#c8b4ed"/>`;
  const top=`<text x="${n.x+13}" y="${n.y+23}" font-size="13" font-weight="bold" font-family="Arial" fill="#332357">${esc(n.label.slice(0,Math.floor((w-28)/7)))}</text>`;
  const second=n.label.length>Math.floor((w-28)/7)?`<text x="${n.x+13}" y="${n.y+40}" font-size="12" font-family="Arial" fill="#332357">${esc(n.label.slice(Math.floor((w-28)/7),Math.floor((w-28)/7)*2))}</text>`:'';
  const notes=String(n.notes||'').split(/\n/).flatMap(t=>t.match(new RegExp('.{1,'+Math.max(12,Math.floor((w-32)/7))+ '}', 'g'))||['']).slice(0,Math.max(0,Math.floor((h-64)/14))).map((text,i)=>`<text x="${n.x+13}" y="${n.y+60+i*14}" font-size="11" font-family="Arial" fill="#51446a">${esc(text)}</text>`).join('');
  return `<g>${rect}${top}${second}${notes}</g>`;
 }).join('');
 const width=Math.min(3200,Math.max(900,...map.nodes.map(n=>n.x+mindMapDimensions(n).w+80))),height=Math.min(2000,Math.max(650,...map.nodes.map(n=>n.y+mindMapDimensions(n).h+80)));
 return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><rect width="${width}" height="${height}" fill="#fcfaff"/>${edges}${nodes}</svg>`;
}
function exportMindMap(asPdf){if(!mindMapDraft)return;const svg=mindMapSVG();if(asPdf){const w=window.open('','_blank');if(!w)return toast('Permita pop-ups para imprimir.');w.document.write('<!doctype html><html><head><title>Mapa mental</title><style>body{margin:0}svg{width:100%;height:auto}@page{size:landscape;margin:8mm}</style></head><body>'+svg+'</body></html>');w.document.close();w.onload=()=>w.print();return}const blob=new Blob([svg],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mapa-mental-'+mindMapDraft.id+'.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

