async function lookupClientCnpj(silent=false){const input=$('[name="document"]');if(!input)return;const cnpj=input.value.replace(/\D/g,'');if(cnpj.length!==14){if(!silent)toast('Informe um CNPJ com 14 números.');return}try{const d=await api('/api/cnpj/'+cnpj),map={document:'cnpj',company:'razaoSocial',name:'nomeFantasia',ie:'ie',phone:'phone',email:'email',zipCode:'zipCode',address:'address',addressNumber:'addressNumber',addressComplement:'addressComplement',district:'district',city:'city',state:'state'};for(const [field,key] of Object.entries(map)){const target=$(`[name="${field}"]`);if(target&&d[key])target.value=d[key]}const name=$('[name="name"]');if(name&&!name.value)name.value=d.nomeFantasia||d.razaoSocial||'';toast('Dados públicos do CNPJ preenchidos.')}catch(e){if(!silent)toast(e.message)}}
function uploadXlsx(input,endpoint,page){const file=input.files?.[0];if(!file)return;if(!/\.xlsx$/i.test(file.name)||file.size>12*1024*1024){toast('Escolha um arquivo .xlsx de até 12 MB.');input.value='';return}const reader=new FileReader();reader.onerror=()=>toast('Falha ao ler Excel.');reader.onload=async()=>{try{const fileBase64=String(reader.result).split(',')[1];const r=await api(endpoint,{method:'POST',body:JSON.stringify({fileBase64})});toast(`Importação: ${r.created} novos, ${r.updated} existentes, ${r.duplicates} repetidos.`);await refresh();loadPage(page)}catch(e){toast(e.message)}finally{input.value=''}};reader.readAsDataURL(file)}
