function renderPipeline(){
 const cols=[["quotation","Cotação"],["sent","Enviado"],["negotiation","Negociação"],["approved","Aprovado"],["rejected","Recusado"]];
 const activeQuotes=cache.quotes.filter(q=>!quoteHasDeliveredOrder(q));
 content.innerHTML=`<div class="pipeline">${cols.map(([st,label])=>`<div class="pipe-col" data-pipe-status="${st}"><h4>${label}</h4>${activeQuotes.filter(q=>q.status===st).map(q=>`<div class="pipe-card" draggable="true" data-quote-id="${q.id}"><b>${q.number}</b><small>${esc(q.clientSnapshot?.company||clientName(q.clientId))}</small><small>${brl(q.total)}</small><small>${q.pipelineMovedBy?`Última movimentação: ${esc(q.pipelineMovedBy)}`:''}</small></div>`).join("")||`<div class="empty">Vazio</div>`}</div>`).join("")}</div>`;
 $$('[data-quote-id]').forEach(c=>{c.ondragstart=e=>{e.dataTransfer.setData('text/plain',c.dataset.quoteId);c.classList.add('dragging')};c.ondragend=()=>c.classList.remove('dragging')});
 $$('[data-pipe-status]').forEach(col=>{col.ondragover=e=>{e.preventDefault();col.classList.add('drag-over')};col.ondragleave=()=>col.classList.remove('drag-over');col.ondrop=async e=>{e.preventDefault();col.classList.remove('drag-over');const id=Number(e.dataTransfer.getData('text/plain'));await api(`/api/quotes/${id}/status`,{method:'PUT',body:JSON.stringify({status:col.dataset.pipeStatus})});toast('Pipeline atualizado');await refresh();renderPipeline()}})
}
async function moveQuote(id,dir){const order=["quotation","sent","negotiation","approved","rejected"],q=cache.quotes.find(x=>x.id===id),i=order.indexOf(q.status),n=order[Math.max(0,Math.min(order.length-1,i+dir))];await api(`/api/quotes/${id}/status`,{method:"PUT",body:JSON.stringify({status:n})});loadPage("pipeline")}

