function renderUsers(list=cache.users){
 content.innerHTML=`<div class="card panel access-summary"><h3>Controle de acesso</h3><p><b>Administrador</b> possui acesso completo. Os demais usuários enxergam somente os módulos autorizados. O Chat é privado: cada conta recebe apenas conversas e comunicações das quais participa.</p></div>`+toolbar("Novo usuário","userForm()")+`<div class="table-wrap"><table><thead><tr><th>Nome</th><th>Login</th><th>E-mail</th><th>Função</th><th>Comissão</th><th>Cadastro</th><th>Ações</th></tr></thead><tbody>${list.map(u=>`<tr><td><b>${esc(u.name)}</b></td><td><b>${esc(u.login||"—")}</b></td><td>${esc(u.email||"—")}</td><td>${esc(u.role||"—")}</td><td>${Number(u.commissionPercent||0).toFixed(2)}%</td><td>${u.active===false?'<span class="badge red">Bloqueado</span>':'<span class="badge green">Liberado</span>'}</td><td><button class="btn btn-light btn-sm" onclick="userForm(${u.id})">Editar acesso</button>${me?.role==='Administrador'&&u.id!==me?.id?` <button class="btn btn-danger btn-sm" onclick="deleteUser(${u.id},'${esc(u.name||u.login||'Usuário')}')">Excluir</button>`:''}</td></tr>`).join("")}</tbody></table></div>`;bindSearch(cache.users,renderUsers)
}
async function deleteUser(id,name){if(!await C4UDialog.confirm(`Excluir definitivamente o acesso de ${name}? Essa pessoa será desconectada e os computadores liberados para ela perderão o acesso automático.`))return;await api(`/api/users/${id}`,{method:'DELETE'});toast('Usuário excluído');await refresh();renderUsers()}
function userForm(id){
 const u=cache.users.find(x=>x.id===id)||{};
 content.innerHTML=`<div class="card page-card">${back(id?"Editar usuário":"Novo usuário","Cadastre o acesso que será usado para entrar no 4Z SYSTEM")}<form id="f" class="form"><div class="form-grid">${field("Nome *","name",u.name,"required")}${field("Login *","login",u.login||"","required autocomplete='off'")}${field("E-mail","email",u.email,"type='email'")}${select("Função","role",u.role||"Vendedor",[["Administrador","Administrador"],["Vendedor","Vendedor"],["Financeiro","Financeiro"],["Produção","Produção"]])}${field("Comissão (%)","commissionPercent",u.commissionPercent||0,"type='number' min='0' step='0.01'")}${select("Acesso liberado","active",u.active===false?"false":"true",[["true","Sim"],["false","Não"]])}${field(id?"Nova senha (deixe vazio para manter)":"Senha *","password","",id?"type='password' minlength='6' autocomplete='new-password'":"type='password' minlength='6' required autocomplete='new-password'")}</div><div class="section-title">Permissões de acesso</div><div class="permission-grid">${[['dashboard','Início / Dashboard'],['chat','Chat'],['prospecting','Prospecção'],['routePlanner','Roteiro'],['clients','Clientes'],['crm','CRM'],['quotes','Orçamentos'],['orders','Pedidos'],['calendar','Calendário'],['tasks','Tarefas'],['finance','Financeiro'],['invoices','Pré-Notas'],['documents','Documentos / Editáveis'],['itemLibrary','Biblioteca'],['products','Produtos'],['suppliers','Fornecedores'],['reports','Relatórios'],['priceHistory','Histórico de Preços'],['approvals','Aprovações'],['filesCenter','Arquivos'],['executive','Painel Executivo'],['notifications','Notificações'],['search','Busca Global']].map(([v,l])=>`<label class="check-field"><input type="checkbox" name="perm_${v}" ${((u.effectivePermissions||u.permissions||[]).includes(v)||(u.role==='Administrador'))?'checked':''} ${u.role==='Administrador'?'disabled':''}><span><b>${l}</b></span></label>`).join('')}</div><div class="form-actions"><button class="btn btn-primary">${id?'Salvar acesso':'Criar acesso'}</button></div></form></div>`;
 $("#f").onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.commissionPercent=Number(d.commissionPercent||0);d.active=d.active==="true";d.permissions=Object.keys(d).filter(k=>k.startsWith('perm_')&&d[k]==='on').map(k=>k.slice(5));Object.keys(d).filter(k=>k.startsWith('perm_')).forEach(k=>delete d[k]);await api(id?`/api/users/${id}`:"/api/users",{method:id?"PUT":"POST",body:JSON.stringify(d)});toast(id?"Acesso atualizado":"Acesso criado");loadPage("users")}
}
