function irisOpen(){const p=$('#irisPanel');if(!p)return;$('#irisDock').classList.add('open');p.classList.remove('hidden');localStorage.setItem('irisOpen-user-'+(me?.id||'guest'),'1');irisRenderContext();if(!$('#irisMessages').children.length)irisSay(`Oi, ${me?.name?.split(' ')[0]||'por aí'}! Eu sou a IRIS ✨\nFico aqui do seu lado para explicar o C4U SIST e ajudar quando surgir uma dúvida. ${irisKnowledge[currentPage]?.hello||''}`)}
function irisClose(){if(!$('#irisPanel'))return;$('#irisDock').classList.remove('open');$('#irisPanel').classList.add('hidden');localStorage.setItem('irisOpen-user-'+(me?.id||'guest'),'0')}
function irisSay(text,who='bot'){const box=$('#irisMessages');if(!box)return;const m=document.createElement('div');m.className=`iris-msg ${who}`;m.textContent=text;box.appendChild(m);box.scrollTop=box.scrollHeight}
function irisRenderContext(){const k=irisKnowledge[currentPage]||irisKnowledge.dashboard;const c=$('#irisContext'),s=$('#irisSuggestions');if(!c||!s)return;c.textContent=`Você está em ${meta[currentPage]?.[0]||'C4U SIST'}`;s.innerHTML=[...(k.tips||[]),'Explicar esta tela'].map(x=>`<button type="button" onclick="irisAsk('${x.replace(/'/g,"\\'")}')">${esc(x)}</button>`).join('')}
function irisAnswer(q){const t=q.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const k=irisKnowledge[currentPage]||{};
 if(t.includes('explicar esta tela')||t.includes('o que vejo aqui'))return `${meta[currentPage]?.[0]} — ${k.hello||meta[currentPage]?.[1]}`;
 if(t.includes('orcamento')&&/(criar|fazer|novo|montar)/.test(t))return 'Para criar um orçamento: abra Orçamentos → Novo orçamento, escolha o cliente, adicione o produto, quantidade, custos, personalização e frete. Confira imposto, margem e comissão. No final você pode apenas salvar ou usar “Salvar e lançar direto para pedido”.';
 if(t.includes('preco')||t.includes('calcul'))return 'No orçamento, o C4U soma mercadoria + personalização + frete, aplica o imposto e depois as margens de lucro e comissão configuradas no item. O resumo mostra custo, imposto, comissão, lucro estimado, margem real e total final.';
 if(t.includes('pedido')&&/(lancar|criar|converter)/.test(t))return 'Abra o orçamento desejado e use a opção de lançar para Pedido. O C4U leva cliente, itens, imagens, valores e prazos para Pedidos / Produção e mantém a ligação com o orçamento original.';
 if(t.includes('pre-nota')||t.includes('nf-e')||t.includes('nfe')||t.includes('nota fiscal'))return 'A Pré-Nota do C4U é um documento interno para conferência e apresentação. Ela não é NF-e nem DANFE oficial. Uma NF-e real exigirá integração fiscal, certificado digital e autorização da SEFAZ.';
 if(t.includes('xbz'))return 'A integração XBZ foi preparada para sincronizar catálogo quando tivermos a documentação/credenciais oficiais da API. A estrutura prevê SKU, nome, descrição, NCM, preço, estoque, imagens e cores, conforme a API disponibilizar.';
 if(t.includes('pdf'))return 'Nos orçamentos e pré-notas, use o botão PDF/Imprimir. O navegador abre a versão formatada e você pode escolher “Salvar como PDF” na janela de impressão.';
 if(t.includes('excluir'))return 'Procure o botão vermelho “Excluir” na linha do registro. O sistema pede confirmação antes de remover. Para dados importantes, recomendo manter um backup antes de exclusões grandes.';
 if(t.includes('cor')||t.includes('mascara'))return currentPage==='quoteTemplate'?'Altere as cores no Editor da máscara. Você também pode mudar título, subtítulo, cor e tamanho do nome do cliente e rodapé; a prévia aparece ao lado antes de salvar.':'As cores gerais ficam em Configurações. A aparência específica do orçamento fica em Máscara de orçamento.';
 if(t.includes('vendedor')||t.includes('relatorio'))return 'Em Relatórios, o administrador pode filtrar período e vendedor para comparar orçamentos, aprovados, perdidos, conversão, pedidos, vendas, ticket médio, comissão e atividades. Usuários sem permissão administrativa têm visão limitada.';
 if(t.includes('follow')||t.includes('atividade')||t.includes('prospecc'))return 'Use o CRM para registrar atividades comerciais e próximos contatos. Em Relatórios você consegue acompanhar volume de atividades e a origem dos clientes/prospecções no período.';
 if(t.includes('senha')||t.includes('login'))return 'O 4Z SYSTEM exige login. O administrador cria os acessos em Usuários; login, e-mail, função e senha ficam vinculados ao cadastro do usuário.';
 return `${k.hello||'Posso ajudar com o C4U SIST.'}\n\nAinda estou na minha primeira versão: conheço o funcionamento do sistema e a tela atual, mas não altero registros sozinha. Tente perguntar “como criar orçamento?”, “como funciona a XBZ?” ou “explicar esta tela”.`}
function irisAsk(q){if(!q)return;irisSay(q,'user');setTimeout(()=>irisSay(irisAnswer(q)),180)}
function initIris(){const b=$('#irisBubble'),cl=$('#irisClose'),f=$('#irisForm'),inp=$('#irisInput');if(!b)return;b.onclick=irisOpen;cl.onclick=irisClose;f.onsubmit=e=>{e.preventDefault();const q=inp.value.trim();if(!q)return;inp.value='';irisAsk(q)};if(me&&localStorage.getItem('irisOpen-user-'+me.id)==='1')irisOpen()}
