function checkboxField(label,name,checked,help=''){return `<label class="check-field"><input type="checkbox" name="${name}" ${checked?'checked':''}><span><b>${esc(label)}</b>${help?`<small>${esc(help)}</small>`:''}</span></label>`}
function optionLabel(o){const s=cache.suppliers.find(x=>x.id===Number(o.supplierId));return s?.name||'Fornecedor'}
function readFileData(file,cb){if(!file)return;const r=new FileReader();r.onload=()=>cb(r.result);r.readAsDataURL(file)}


// Pesquisa de catálogo v16.0.5: descrição e categoria NÃO participam da busca padrão.
function productSearchNormalize(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase()}
function productSearchRank(p,query){const q=productSearchNormalize(query),qc=q.replace(/\s+/g,'');if(!q)return 1;
 const code=productSearchNormalize(p.internalCode||p.code||p.sku).replace(/\s+/g,''),supplier=productSearchNormalize(p.supplierCode).replace(/\s+/g,''),parent=productSearchNormalize(p.parentCode).replace(/\s+/g,''),name=productSearchNormalize(p.name);
 if(code&&code===qc)return 110;if(supplier&&supplier===qc)return 105;if(parent&&parent===qc)return 100;if(code&&code.startsWith(qc))return 95;if(supplier&&supplier.startsWith(qc))return 92;if(parent&&parent.startsWith(qc))return 88;
 if(name===q)return 90;if(name.startsWith(q))return 80;if(name.split(/[^a-z0-9]+/).some(w=>w.startsWith(q)))return 70;if(name.includes(q))return 60;return 0}
function productSearch(items,query){return items.map((p,index)=>({p,index,score:productSearchRank(p,query)})).filter(x=>x.score).sort((a,b)=>b.score-a.score||a.index-b.index).map(x=>x.p)}
async function dedupeLibraryImages(){if(!await C4UDialog.confirm('Remover APENAS cópias exatamente iguais dentro do MESMO produto? O sistema criará backup do banco antes de alterar. Cores e fotos entre produtos distintos não serão modificadas.'))return;try{const r=await api('/api/itemLibrary/quality/dedupe',{method:'POST',body:'{}'});toast(`Corrigidos ${r.itemsChanged} itens; ${r.imagesRemoved} imagens repetidas removidas.`);$('#qualityOverlay')?.remove();await refresh();renderItemLibrary(filterLibrary())}catch(e){toast(e.message)}}
async function showLibraryQuality(){try{const d=await api('/api/itemLibrary/quality');const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='qualityOverlay';overlay.innerHTML=`<div class="modal-card c4u-quality-modal"><div class="page-head"><div><h2>Conferência de produtos</h2><p>${d.count} alerta(s) em ${d.total} produtos • somente leitura: nenhuma foto foi trocada automaticamente.</p></div><button class="btn btn-light" onclick="document.getElementById('qualityOverlay').remove()">Fechar ×</button></div><div class="quality-results">${d.issues.length?d.issues.map(x=>`<div class="quality-entry"><b>${esc(x.code||'Sem código')} · ${esc(x.name||'Item')}</b><small>${esc(x.detail)}</small><button class="btn btn-light btn-sm" onclick="document.getElementById('qualityOverlay').remove();libraryItemForm(${Number(x.itemId)})">Conferir item</button></div>`).join(''):'<p>Nenhuma inconsistência detectada pelas regras automáticas. A correção das fotos ainda exige conferência visual.</p>'}${d.truncated?'<p>Exibindo os primeiros 1.500 alertas.</p>':''}</div><div class="form-actions"><button class="btn btn-light" onclick="dedupeLibraryImages()">Remover apenas imagens idênticas repetidas no mesmo item</button></div></div>`;document.body.appendChild(overlay)}catch(e){toast(e.message)}}
// BIBLIOTECA DE ITENS
let libraryView='list';
let libraryFilterState={q:'',cat:'',sub:'',supplier:'Todos'};
// Catálogo único de consulta: o backend relaciona SPOT, biblioteca, estoque físico e futuras APIs.
let unifiedLibraryRequest=0,unifiedLibraryOffset=0,unifiedLibraryPageSize=48;
function unifiedCatalogBadge(item){return `<span class="c4u-unified-source">${esc(item.source||'Cadastro')}</span>`}
function unifiedCatalogThumb(item){return item.image?`<img src="${esc(item.image)}" alt="" loading="lazy" onerror="this.style.display='none'">`:'▦'}
function unifiedLibraryActions(item,index){
 if(item.kind==='library')return `<button class="btn btn-light btn-sm" data-unified-action="edit" data-index="${index}">Editar</button>`;
 if(item.kind==='stock')return `<button class="btn btn-light btn-sm" data-unified-action="stock" data-index="${index}">Ver estoque</button>`;
 return `<button class="btn btn-light btn-sm" data-unified-action="detail" data-index="${index}">Ver detalhes</button>`;
}
function renderItemLibrary(){
 const q=libraryFilterState.q||'';
 const controls=`<div class="page-head"><div><h2>Biblioteca de itens</h2><p>Um único catálogo: produtos cadastrados, importados, estoque físico e fornecedores integrados.</p></div></div><div class="toolbar library-toolbar c4u-unified-toolbar"><div class="confirmed-search"><input id="search" class="search" value="${esc(q)}" placeholder="Nome, código, referência ou SKU · qualquer origem" aria-label="Pesquisar todos os produtos"><button type="button" id="librarySearchConfirm" class="btn btn-primary">⌕ Buscar</button></div><div class="view-actions"><button class="btn btn-light" id="clearUnifiedSearch">Limpar</button><button class="btn btn-light" onclick="libraryView='list';renderItemLibrary()">☷ Lista</button><button class="btn btn-light" onclick="libraryView='cards';renderItemLibrary()">▦ Cards</button>${me?.role==='Administrador'?'<button class="btn btn-light" onclick="showLibraryQuality()">Conferir biblioteca manual</button><button class="btn btn-light" onclick="previewSpreadsheetCleanup()">Limpar itens da planilha</button>':''}<button class="btn btn-primary" onclick="libraryItemForm()">+ Novo item</button></div></div><div class="c4u-unified-info">Catálogos SPOT, Só Marcas, Ásia e XBZ disponíveis para orçamentos. Origem e estoques de cada fornecedor permanecem separados.</div>`;
 content.innerHTML=controls+'<nav class="c4u-supplier-tabs" id="supplierTabs" aria-label="Filtrar por fornecedor"></nav><div class="c4u-catalog-filters"><label>Categoria<select id="unifiedCategory"><option value="">Todas as categorias</option></select></label><label>Subcategoria<select id="unifiedSubcategory"><option value="">Todas as subcategorias</option></select></label></div><div id="unifiedLibraryResults" aria-live="polite">Consultando catálogo...</div>';
 const input=$('#search'),run=()=>{libraryFilterState.q=input.value.trim();unifiedLibraryOffset=0;loadUnifiedLibraryView()};
 $('#librarySearchConfirm').onclick=run;
 input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();run()}};
 let timer;input.oninput=()=>{clearTimeout(timer);timer=setTimeout(run,300)};
 $('#clearUnifiedSearch').onclick=()=>{input.value='';run();input.focus()};
 
 loadUnifiedLibraryView();
}
function paintLibrarySupplierFilters(result){
 const tabs=$('#supplierTabs');if(!tabs)return;
 tabs.innerHTML=(result.tabs||['Todos','SPOT','XBZ','Ásia','Só Marcas','Manuais']).map(name=>`<button type="button" class="c4u-supplier-tab ${name===libraryFilterState.supplier?'active':''}" data-supplier="${esc(name)}" aria-pressed="${name===libraryFilterState.supplier?'true':'false'}">${esc(name)} <small>${Number(result.counts?.[name]||0)}</small></button>`).join('');
 tabs.querySelectorAll('[data-supplier]').forEach(button=>button.onclick=()=>{libraryFilterState.supplier=button.dataset.supplier;libraryFilterState.cat='';libraryFilterState.sub='';unifiedLibraryOffset=0;loadUnifiedLibraryView()});
 const cat=$('#unifiedCategory'),sub=$('#unifiedSubcategory');if(!cat||!sub)return;
 const categories=result.categories||[],subcategories=result.subcategories||[];
 cat.innerHTML='<option value="">Todas as categorias</option>'+categories.map(x=>`<option value="${esc(x)}" ${x===libraryFilterState.cat?'selected':''}>${esc(x)}</option>`).join('');
 sub.innerHTML='<option value="">Todas as subcategorias</option>'+subcategories.map(x=>`<option value="${esc(x)}" ${x===libraryFilterState.sub?'selected':''}>${esc(x)}</option>`).join('');
 cat.onchange=()=>{libraryFilterState.cat=cat.value;libraryFilterState.sub='';unifiedLibraryOffset=0;loadUnifiedLibraryView()};
 sub.onchange=()=>{libraryFilterState.sub=sub.value;unifiedLibraryOffset=0;loadUnifiedLibraryView()};
}
async function previewSpreadsheetCleanup(){
 let d;try{d=await api('/api/itemLibrary/spreadsheet-cleanup/preview')}catch(e){return toast(e.message)}
 const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='spreadsheetCleanupOverlay';
 overlay.innerHTML=`<div class="modal-card c4u-sheet-cleanup"><div class="page-head"><div><h2>Limpeza controlada — planilha de produtos</h2><p>Somente itens identificados com origem exata Asia Import - planilha.</p></div><button class="btn btn-light" id="closeSheetCleanup">Fechar ×</button></div><div class="c4u-unified-info">${esc(d.warning)}</div><p><b>${d.candidates}</b> ativos identificados · <b>${d.deleteCount}</b> exclusões seguras · <b>${d.archiveCount}</b> arquivamentos de itens usados ou editados · ${d.alreadyInactive} já inativos.</p><div class="c4u-cleanup-samples">${d.samples.map(x=>`<div><b>${esc(x.code||'Sem código')}</b> · ${esc(x.name)}<small>${esc(x.action)} ${esc(x.reason||'')}</small></div>`).join('')||'<p>Nenhum produto ativo da planilha encontrado.</p>'}</div><p><b>Atenção:</b> não apaga planilhas gerais, produtos SPOT, APIs, estoque físico, orçamentos ou pedidos. Um backup do banco será criado antes de gravar.</p><label>Para confirmar, digite LIMPAR PLANILHA<input id="sheetCleanupConfirm" autocomplete="off" placeholder="LIMPAR PLANILHA"></label><div class="form-actions"><button class="btn btn-light" id="cancelSheetCleanup">Cancelar</button><button class="btn btn-danger" id="runSheetCleanup" ${!d.candidates?'disabled':''}>Confirmar limpeza</button></div></div>`;
 document.body.appendChild(overlay);
 const close=()=>overlay.remove();overlay.querySelector('#closeSheetCleanup').onclick=close;overlay.querySelector('#cancelSheetCleanup').onclick=close;
 overlay.querySelector('#runSheetCleanup').onclick=async()=>{
  const confirmation=overlay.querySelector('#sheetCleanupConfirm').value;
  if(confirmation!=='LIMPAR PLANILHA')return toast('Digite LIMPAR PLANILHA exatamente.');
  if(!await C4UDialog.confirm(`Confirmar limpeza de ${d.candidates} registros da planilha? Os vinculados/editados serão arquivados.`))return;
  try{const r=await api('/api/itemLibrary/spreadsheet-cleanup/execute',{method:'POST',body:JSON.stringify({token:d.token,confirmation})});
   close();toast(`Planilha: ${r.deleted} excluídos e ${r.archived} arquivados. Backup: ${r.backup||'nenhum'}`);await refresh();renderItemLibrary();
  }catch(e){toast(e.message)}
 };
}
async function loadUnifiedLibraryView(){
 const q=libraryFilterState.q.trim(),dest=$('#unifiedLibraryResults'),request=++unifiedLibraryRequest;
 if(!dest)return;dest.textContent='Consultando todas as origens...';
 try{
  const result=await api('/api/catalog/unified?'+new URLSearchParams({q,offset:String(unifiedLibraryOffset),limit:String(unifiedLibraryPageSize),supplier:libraryFilterState.supplier||'Todos',category:libraryFilterState.cat||'',subcategory:libraryFilterState.sub||''}).toString());
  if(request!==unifiedLibraryRequest||!$('#unifiedLibraryResults'))return;
  const rows=result.items||[];window._unifiedLibraryResults=rows;
  paintLibrarySupplierFilters(result);
  const summary=`<div class="c4u-unified-summary"><strong>${result.total} resultado(s)</strong><span>${result.total?`Exibindo ${result.offset+1}–${result.offset+rows.length}`:'Refine sua pesquisa'} · ${esc(result.supplier||'Todos')} · busca unificada</span></div>`;
  const card=rows.map((item,i)=>`<article class="library-card c4u-unified-card"><div class="library-card-image">${unifiedCatalogThumb(item)}</div><div class="library-card-body">${unifiedCatalogBadge(item)}<h3>${esc(item.name)}</h3><p>${esc(item.code||'Sem código')}${item.color?' · '+esc(item.color):''}</p><div class="library-price"><span>${item.kind==='somarcas'?'Referência s/ gravação, c/ impostos':'Custo de referência'}</span><b>${item.cost===null?'—':brl(item.cost)}</b><span>Estoque ${['spot','somarcas'].includes(item.kind)?'fornecedor':item.kind==='stock'?'físico':''}</span><b>${item.stock===null?'—':esc(item.stock)}</b></div><div class="card-actions">${unifiedLibraryActions(item,i)}</div></div></article>`).join('');
  const table=`<div class="table-wrap"><table><thead><tr><th>Produto</th><th>Origem</th><th>Código / SKU</th><th>Cor</th><th>Estoque</th><th>Custo referência</th><th>Ações</th></tr></thead><tbody>${rows.map((item,i)=>`<tr><td><div class="table-product"><div class="mini-product-img">${unifiedCatalogThumb(item)}</div><div><b>${esc(item.name)}</b></div></div></td><td>${unifiedCatalogBadge(item)}</td><td>${esc(item.code||'—')}</td><td>${esc(item.color||'—')}</td><td>${item.stock===null?'—':esc(item.stock)}</td><td>${item.cost===null?'—':brl(item.cost)}</td><td>${unifiedLibraryActions(item,i)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Nenhum produto encontrado.</td></tr>'}</tbody></table></div>`;
  const pages=`<nav class="c4u-unified-pages"><button class="btn btn-light" id="unifiedPrevious" ${result.offset===0?'disabled':''}>← Anterior</button><span>${Math.floor(result.offset/unifiedLibraryPageSize)+1} / ${Math.max(1,Math.ceil(result.total/unifiedLibraryPageSize))}</span><button class="btn btn-light" id="unifiedNext" ${result.offset+rows.length>=result.total?'disabled':''}>Próxima →</button></nav>`;
  dest.innerHTML=summary+(libraryView==='cards'?`<div class="library-grid c4u-unified-grid">${card}</div>`:table)+pages;
  dest.querySelectorAll('[data-unified-action]').forEach(btn=>btn.onclick=()=>{
   const item=rows[Number(btn.dataset.index)];if(!item)return;
   if(btn.dataset.unifiedAction==='edit')libraryItemForm(Number(item.id));
   else if(btn.dataset.unifiedAction==='stock')loadPage('products');
   else openUnifiedLibraryDetails(item);
  });
  $('#unifiedPrevious').onclick=()=>{unifiedLibraryOffset=Math.max(0,unifiedLibraryOffset-unifiedLibraryPageSize);loadUnifiedLibraryView()};
  $('#unifiedNext').onclick=()=>{unifiedLibraryOffset+=unifiedLibraryPageSize;loadUnifiedLibraryView()};
 }catch(e){if(request===unifiedLibraryRequest&&$('#unifiedLibraryResults'))dest.textContent='Falha ao consultar o catálogo unificado: '+e.message}
}
function openUnifiedLibraryDetails(item){
 const somarcasExtra=item.kind==='somarcas'?`<h3>Quatro opções de preço — Só Marcas</h3>${somarcasPriceTable(item.prices)}<p><b>Gravação:</b> ${esc(item.engravingType||'—')}</p><small>Preços informativos sujeitos à confirmação comercial. Escolha a modalidade ao adicionar ao orçamento.</small>`:'';
 const xbzExtra=item.kind==='xbz'?`<h3>Detalhes XBZ</h3><p><b>Código comercial:</b> ${esc(item.code)} · <b>Variação:</b> ${esc(item.variationCode||'—')} · <b>ID interno:</b> ${esc(item.internalCode||'—')} · <b>Atualizado:</b> ${item.lastSupplierSync?esc(dmy(item.lastSupplierSync)):'—'}</p><small>Estoque e preço do cache, sujeitos à confirmação com o fornecedor. Este catálogo não envia compras.</small>`:'';
 const asiaExtra=item.kind==='asia'?`<h3>Detalhes da Ásia Import</h3><p><b>Referência-pai:</b> ${esc(item.parentCode||'—')} · <b>SKU:</b> ${esc(item.code)} · <b>Cor/variação:</b> ${esc(item.color||'—')}<br><b>Estoque em SP:</b> ${item.stockSP===null?'—':esc(item.stockSP)} · <b>Origem de faturamento:</b> ${esc(item.origin||'—')}</p><small>Preço e estoque sujeitos à confirmação. O custo é copiado para o orçamento e permanece registrado no item salvo.</small>`:'';
 const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='unifiedItemDetails';
 overlay.innerHTML=`<div class="modal-card c4u-unified-detail"><div class="c4u-detail-head"><div><span class="c4u-detail-source">${unifiedCatalogBadge(item)}</span><h2>${esc(item.name)}</h2><p>${esc(item.code||'Sem código')}${item.color?' · '+esc(item.color):''}</p></div><button class="btn btn-light c4u-detail-close" onclick="document.getElementById('unifiedItemDetails').remove()">×</button></div><div class="c4u-detail-main"><div class="c4u-detail-media">${item.image?`<img src="${esc(item.image)}" class="c4u-unified-detail-image" alt="Foto do produto">`:'<div class="c4u-detail-no-image">Sem imagem</div>'}</div><div class="c4u-detail-data"><div class="c4u-detail-metrics"><div><small>Estoque</small><b>${item.stock===null?'—':esc(item.stock)}</b></div><div><small>Custo</small><b>${item.cost===null?'—':brl(item.cost)}</b></div><div><small>Origem</small><b>${esc(item.source||'Cadastro')}</b></div></div><p class="c4u-detail-description">${esc(item.description||'Sem descrição adicional.')}</p>${somarcasExtra}${asiaExtra}${xbzExtra}</div></div><div class="c4u-detail-footer"><small>Origem preservada. Esta consulta não altera item, estoque físico ou orçamento.</small><button class="btn btn-primary" onclick="document.getElementById('unifiedItemDetails').remove()">Fechar</button></div></div>`;
 document.body.appendChild(overlay);
}
function libraryBestCost(p){const opts=(p.supplierOptions||[]).filter(x=>Number(x.cost)>0);return opts.length?Math.min(...opts.map(x=>Number(x.cost))):Number(p.cost||0)}
function filterLibrary(){return productSearch(cache.itemLibrary.filter(x=>x.active!==false),libraryFilterState.q||'')}
function libraryItemForm(id){
 const p=cache.itemLibrary.find(x=>x.id===id)||{};window.libImages=[...(p.images||[])];window.libSupplierOptions=(p.supplierOptions||[]).map(x=>({...x}));if(!window.libSupplierOptions.length)window.libSupplierOptions=[{supplierId:p.supplierId||0,supplierCode:p.supplierCode||'',cost:p.cost||0,minQty:p.minQty||0,leadTime:p.leadTime||''}];
 content.innerHTML=`<div class="card page-card">${back(id?'Editar item da Biblioteca':'Novo item da Biblioteca','Cadastre uma vez e reutilize em todo o C4U')}<form id="libraryForm" class="form">
 <div class="section-title">Identificação</div><div class="form-grid">${field('Código interno','internalCode',p.internalCode||'')}${field('Nome do item *','name',p.name||'','required')}${select('Status','active',p.active===false?'false':'true',[['true','Ativo'],['false','Inativo']])}${field('Categoria','category',p.category||'')}${field('Subcategoria','subcategory',p.subcategory||'')}${field('Quantidade mínima geral','minQty',p.minQty||0,"type='number' min='0'")}</div>
 <div class="section-title">Informações comerciais e técnicas</div><div class="form-grid">${field('Material','material',p.material||'')}${field('Medidas','dimensions',p.dimensions||'')}${field('Capacidade','capacity',p.capacity||'')}${field('Cores disponíveis','colors',Array.isArray(p.colors)?p.colors.join(', '):(p.colors||''))}${field('Tipos de personalização','personalizationTypes',Array.isArray(p.personalizationTypes)?p.personalizationTypes.join(', '):(p.personalizationTypes||''))}${field('Área de gravação','engravingArea',p.engravingArea||'')}${field('Preço sugerido','suggestedPrice',p.suggestedPrice||0,"type='number' step='0.01' min='0'")}${field('Prazo médio geral','leadTime',p.leadTime||'')}</div>${textarea('Descrição comercial','commercialDescription',p.commercialDescription||'','span3')}${textarea('Descrição técnica','technicalDescription',p.technicalDescription||'','span3')}${textarea('Observações internas','notes',p.notes||'','span3')}
 <div class="section-title">Imagens do item</div><div class="image-library-editor"><div id="libraryImages" class="image-strip"></div><label class="upload-box">+ Adicionar imagens<input id="libraryImageInput" type="file" accept="image/*" multiple hidden></label></div>
 <div class="section-title">Fornecedores deste item</div><p class="form-help">O mesmo item pode ter vários fornecedores, códigos, custos, mínimos e prazos diferentes.</p><div id="librarySupplierRows"></div><button type="button" class="btn btn-light" onclick="addLibrarySupplier()">+ Adicionar fornecedor</button>
 <details class="details-block"><summary>Controle de estoque opcional</summary><div class="details-content"><div class="form-grid">${select('Controlar estoque deste cadastro','stockManaged',p.stockManaged?'true':'false',[['false','Não'],['true','Sim']])}${field('Saldo atual','stock',p.stock||0,"type='number' min='0'")}${field('Estoque mínimo','minStock',p.minStock||0,"type='number' min='0'")}</div><p class="form-help">A Biblioteca é o catálogo mestre. Estoque físico está separado nesta guia e seus proprietários são clientes cadastrados.</p></div></details>
 <div class="form-actions"><button type="button" class="btn btn-light" onclick="loadPage('itemLibrary')">Cancelar</button><button class="btn btn-primary">Salvar item</button></div></form></div>`;
 renderLibraryImages();renderLibrarySupplierRows();
 $('#libraryImageInput').onchange=e=>{[...e.target.files].forEach(file=>readFileData(file,data=>{window.libImages.push(data);renderLibraryImages()}));e.target.value=''};
 $('#libraryForm').onsubmit=async e=>{e.preventDefault();syncLibrarySuppliers();const d=Object.fromEntries(new FormData(e.target));d.active=d.active==='true';d.stockManaged=d.stockManaged==='true';['minQty','suggestedPrice','stock','minStock'].forEach(k=>d[k]=Number(d[k]||0));d.colors=String(d.colors||'').split(',').map(x=>x.trim()).filter(Boolean);d.personalizationTypes=String(d.personalizationTypes||'').split(',').map(x=>x.trim()).filter(Boolean);d.images=window.libImages;d.supplierOptions=window.libSupplierOptions.filter(x=>Number(x.supplierId)||x.supplierCode||Number(x.cost));const best=d.supplierOptions.slice().sort((a,b)=>Number(a.cost||Infinity)-Number(b.cost||Infinity))[0]||{};d.supplierId=Number(best.supplierId)||0;d.supplierCode=best.supplierCode||'';d.cost=Number(best.cost)||0;await api(id?`/api/itemLibrary/${id}`:'/api/itemLibrary',{method:id?'PUT':'POST',body:JSON.stringify(d)});toast('Item da Biblioteca salvo');loadPage('itemLibrary')}
}
function renderLibraryImages(){const b=$('#libraryImages');if(!b)return;b.innerHTML=window.libImages.map((img,i)=>`<div class="image-tile"><img src="${img}"><button type="button" onclick="window.libImages.splice(${i},1);renderLibraryImages()">×</button>${i===0?'<small>Principal</small>':''}</div>`).join('')||'<div class="empty small-empty">Nenhuma imagem.</div>'}
function addLibrarySupplier(){syncLibrarySuppliers();window.libSupplierOptions.push({supplierId:0,supplierCode:'',cost:0,minQty:0,leadTime:''});renderLibrarySupplierRows()}
function removeLibrarySupplier(i){syncLibrarySuppliers();window.libSupplierOptions.splice(i,1);if(!window.libSupplierOptions.length)window.libSupplierOptions.push({supplierId:0,supplierCode:'',cost:0,minQty:0,leadTime:''});renderLibrarySupplierRows()}
function syncLibrarySuppliers(){$$('.supplier-option-row').forEach((r,i)=>{window.libSupplierOptions[i]={supplierId:Number($('[name="supplierId"]',r)?.value)||0,supplierCode:$('[name="supplierCode"]',r)?.value||'',cost:Number($('[name="cost"]',r)?.value)||0,minQty:Number($('[name="minQty"]',r)?.value)||0,leadTime:$('[name="leadTime"]',r)?.value||''}})}
function renderLibrarySupplierRows(){const b=$('#librarySupplierRows');if(!b)return;b.innerHTML=window.libSupplierOptions.map((o,i)=>`<div class="supplier-option-row"><div class="supplier-row-index">${i+1}</div>${select('Fornecedor','supplierId',o.supplierId||'',[['','Selecione...'],...cache.suppliers.map(s=>[s.id,s.name])])}${field('Código do fornecedor','supplierCode',o.supplierCode||'')}${field('Custo','cost',o.cost||0,"type='number' min='0' step='0.01'")}${field('Mínimo','minQty',o.minQty||0,"type='number' min='0'")}${field('Prazo','leadTime',o.leadTime||'')}<button type="button" class="btn btn-danger btn-sm supplier-remove" onclick="removeLibrarySupplier(${i})">×</button></div>`).join('')}
async function duplicateLibraryItem(id){try{await api(`/api/itemLibrary/${id}/duplicate`,{method:'POST',body:'{}'});toast('Item duplicado');loadPage('itemLibrary')}catch(e){toast(e.message)}}

// ADICIONAR BIBLIOTECA AO ORÇAMENTO — cria cópia independente do cadastro mestre
// Mesmo campo de pesquisa usado na Biblioteca: nenhuma lista SPOT separada no final do modal.
let unifiedPickerRequest=0;
function openLibraryPicker(initialQuery=""){
 const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='libraryPicker';
 overlay.innerHTML=`<div class="modal-card library-picker c4u-unified-picker"><div class="page-head"><div><h2>Adicionar produto ao orçamento</h2><p>Pesquise por nome, código ou SKU em todas as origens. O item será copiado para este orçamento.</p></div><button class="btn btn-light" onclick="document.getElementById('libraryPicker').remove()">× Fechar</button></div><div class="confirmed-search c4u-picker-search"><input id="libPickSearch" class="search" value="${esc(initialQuery)}" placeholder="Buscar qualquer produto · nome, código ou SKU" aria-label="Pesquisar todo o catálogo"><button type="button" class="btn btn-primary" id="libPickConfirm">⌕ Buscar</button></div><small class="c4u-unified-picker-hint">Biblioteca, SPOT, Só Marcas, importados e estoque físico — uma única busca. Nenhum pedido é enviado aos fornecedores.</small><div id="libPickResults" class="picker-results c4u-unified-picker-results" aria-live="polite"></div></div>`;
 document.body.appendChild(overlay);
 const input=$('#libPickSearch'),results=$('#libPickResults');let timer;
 const paint=async()=>{
  const query=input.value.trim(),request=++unifiedPickerRequest;
  if(query.length<2){results.innerHTML='<div class="empty">Digite pelo menos 2 caracteres para encontrar produtos de qualquer origem.</div>';return}
  results.textContent='Buscando produtos em todas as origens...';
  try{
   const data=await api('/api/catalog/unified?q='+encodeURIComponent(query)+'&limit=90');
   if(request!==unifiedPickerRequest||!document.getElementById('libraryPicker'))return;
   const clientId=Number($('#qf [name="clientId"]')?.value||0);
   const items=(data.items||[]).filter(item=>item.kind!=='stock'||!item.ownerClientId||Number(item.ownerClientId)===clientId);
   window._unifiedPickerResults=items;
   results.innerHTML=`<p class="c4u-unified-picker-count">${data.total} encontrado(s). ${data.total>data.items.length?'Refine a pesquisa para ver mais resultados.':''}</p>`+
    (items.length?items.map((item,i)=>`<button type="button" class="picker-item" data-unified-pick="${i}"><span class="picker-thumb">${unifiedCatalogThumb(item)}</span><span><b>${esc(item.name)} ${item.color?'· '+esc(item.color):''}</b><small>${unifiedCatalogBadge(item)} · ${esc(item.code||'Sem código')}${item.stock!==null?' · disponível '+esc(item.stock):''}</small><small>${item.kind==='somarcas'?'Quatro opções de preço · escolha modalidade':`Custo referência: ${item.cost===null?'—':brl(item.cost)}${item.kind==='spot'?' · ajuste automático por quantidade':''}`}</small></span><strong>Adicionar</strong></button>`).join(''):'<div class="empty">Nenhum produto encontrado.</div>');
   results.querySelectorAll('[data-unified-pick]').forEach(btn=>btn.onclick=()=>addUnifiedPickerResult(Number(btn.dataset.unifiedPick)));
  }catch(e){if(request===unifiedPickerRequest&&document.getElementById('libraryPicker'))results.textContent=e.message}
 };
 $('#libPickConfirm').onclick=paint;input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();paint()}};
 input.oninput=()=>{clearTimeout(timer);timer=setTimeout(paint,260)};
 paint();setTimeout(()=>input.focus(),0);
}
function addUnifiedPickerResult(index){
 const item=(window._unifiedPickerResults||[])[index];if(!item)return;
 if(item.kind==='library')return addLibraryItemToQuote(Number(item.id));
 if(item.kind==='stock')return addStockItemToQuote(Number(item.id));
 if(item.kind==='spot')return openSpotQuoteItem(item);
 if(item.kind==='somarcas')return openSomarcasQuoteItem(item);
 if(item.kind==='asia')return openAsiaQuoteItem(item);
 if(item.kind==='xbz')return openXbzQuoteItem(item);
 if(item.kind==='product'){
  if(!Array.isArray(window.qItems))return;
  window.qItems.push({...blankItem(),productId:Number(item.id)||0,productName:item.name,description:item.description||item.name,supplierId:Number(item.supplierId)||0,supplierCode:item.code||'',qty:50,unitCost:Number(item.cost)||0,image:item.image||''});
  document.getElementById('libraryPicker')?.remove();paintItems();calcUI();toast('Produto adicionado ao orçamento.');
 }
}
// Modal interno: preço é escolhido entre as QUATRO opções recebidas. Nunca cria pedido no fornecedor.
// Escolha de SKU da Ásia; custo e disponibilidade ficam congelados no orçamento salvo.
function openXbzQuoteItem(item){
 if(!item||!Array.isArray(window.qItems))return;
 if(item.cost===null||!Number.isFinite(Number(item.cost))||Number(item.cost)<0)return toast('Produto XBZ sem preço. Consulte o fornecedor antes de orçar.');
 document.getElementById('xbzQuoteModal')?.remove();
 const modal=document.createElement('div');modal.className='modal-overlay';modal.id='xbzQuoteModal';
 modal.innerHTML=`<div class="modal-card c4u-somarcas-choice" role="dialog" aria-modal="true" aria-label="Adicionar item XBZ"><div class="page-head"><div><h2>${esc(item.name)}</h2><p>XBZ · Código ${esc(item.code)} · Variação ${esc(item.variationCode||'—')} · ID ${esc(item.internalCode||'—')}</p></div><button type="button" class="btn btn-light" id="closeXbzQuote">×</button></div>${item.image?`<img src="${esc(item.image)}" class="c4u-unified-detail-image" alt="Foto do produto">`:''}<p><b>Custo de referência:</b> ${brl(item.cost)} · <b>Estoque total disponível:</b> ${item.stock??'—'}${item.stockStatus==='negative'?' · Saldo negativo no fornecedor, tratar como indisponível.':''}</p><label class="c4u-somarcas-choose-label">Quantidade<input type="number" id="xbzQuoteQty" min="1" step="1" value="50"></label><p class="c4u-somarcas-warning">Preço e estoque sujeitos à confirmação comercial. Custo copiado para o orçamento, sem compra no fornecedor.</p><div class="form-actions"><button type="button" class="btn btn-light" id="cancelXbzQuote">Cancelar</button><button type="button" class="btn btn-primary" id="confirmXbzQuote">Adicionar ao orçamento</button></div></div>`;
 document.body.appendChild(modal);const close=()=>modal.remove();$('#closeXbzQuote').onclick=close;$('#cancelXbzQuote').onclick=close;
 $('#confirmXbzQuote').onclick=()=>{const qty=Number($('#xbzQuoteQty').value);if(!Number.isSafeInteger(qty)||qty<1)return toast('Informe uma quantidade inteira positiva.');const cost=Number(item.cost);
 window.qItems.push({...blankItem(),productName:item.name,description:item.description||item.name,qty,unitCost:cost,supplierCode:item.code,image:item.image||'',xbzSnapshot:{source:'XBZ',sku:item.internalCode||item.id,commercialCode:item.code,variationCode:item.variationCode||'',costAtQuote:cost,stockAtQuote:item.stock??null,stockReportedAtQuote:item.stockReported??null,importedAt:item.lastSupplierSync||'',ordersToSupplier:false}});
 close();document.getElementById('libraryPicker')?.remove();paintItems();calcUI();toast('Produto XBZ adicionado ao orçamento.');};$('#xbzQuoteQty').focus();
}
function openAsiaQuoteItem(item){
 if(!item||!Array.isArray(window.qItems))return;
 if(item.cost===null||item.cost===undefined||!Number.isFinite(Number(item.cost))||Number(item.cost)<0)return toast('Este SKU da Ásia está sem preço. Confirme com o fornecedor.');
 document.getElementById('asiaQuoteModal')?.remove();
 const modal=document.createElement('div');modal.className='modal-overlay';modal.id='asiaQuoteModal';
 modal.innerHTML=`<div class="modal-card c4u-somarcas-choice" role="dialog" aria-modal="true" aria-label="Adicionar produto Ásia ao orçamento"><div class="page-head"><div><h2>${esc(item.name)}</h2><p>Ásia Import · SKU ${esc(item.code)} · Pai ${esc(item.parentCode||'—')}</p></div><button type="button" class="btn btn-light" id="closeAsiaQuote">×</button></div>${item.image?`<img class="c4u-unified-detail-image" src="${esc(item.image)}" alt="Foto do produto">`:''}<p><b>Custo informado:</b> ${brl(item.cost)}<br><b>Estoque geral:</b> ${item.stock??'Não informado'} · <b>SP:</b> ${item.stockSP??'Não informado'}</p><label class="c4u-somarcas-choose-label">Quantidade<input type="number" id="asiaQuoteQty" min="1" step="1" value="50"></label><p class="c4u-somarcas-warning">Preço e estoque sujeitos à confirmação com a Ásia Import. Este botão não envia compras ao fornecedor.</p><div class="form-actions"><button type="button" class="btn btn-light" id="cancelAsiaQuote">Cancelar</button><button type="button" class="btn btn-primary" id="confirmAsiaQuote">Adicionar ao orçamento</button></div></div>`;
 document.body.appendChild(modal);$('#closeAsiaQuote').onclick=()=>modal.remove();$('#cancelAsiaQuote').onclick=()=>modal.remove();
 $('#confirmAsiaQuote').onclick=()=>{const qty=Number($('#asiaQuoteQty').value);if(!Number.isSafeInteger(qty)||qty<1)return toast('Informe uma quantidade inteira maior que zero.');
 window.qItems.push({...blankItem(),productName:item.name,description:item.description||item.name,qty,unitCost:Number(item.cost),supplierCode:item.code,image:item.image||'',asiaSnapshot:{source:'Ásia Import',sku:item.code,parentCode:item.parentCode||'',costAtQuote:Number(item.cost),stockAtQuote:item.stock??null,stockSPAtQuote:item.stockSP??null,importedAt:item.lastSupplierSync||'',ordersToSupplier:false}});
 modal.remove();document.getElementById('libraryPicker')?.remove();paintItems();calcUI();toast('Produto Ásia adicionado. Custo copiado para o orçamento.');};$('#asiaQuoteQty').focus();
}
function openSomarcasQuoteItem(item){
 if(!item||!Array.isArray(window.qItems))return;
 const prices=item.prices||{},choices=SOMARCAS_PRICE_CHOICES.filter(p=>prices[p.key]!==null&&prices[p.key]!==undefined&&Number.isFinite(Number(prices[p.key]))&&Number(prices[p.key])>=0);
 if(!choices.length)return toast('Este produto não possui preço disponível na Só Marcas.');
 document.getElementById('somarcasPriceModal')?.remove();
 const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='somarcasPriceModal';
 overlay.innerHTML=`<div class="modal-card c4u-somarcas-choice" role="dialog" aria-modal="true" aria-label="Escolher modalidade de preço Só Marcas"><div class="page-head"><div><h2>${esc(item.name)}</h2><p>Só Marcas · ${esc(item.code)} · Estoque do fornecedor: ${item.stock===null?'—':esc(item.stock)}</p></div><button class="btn btn-light" id="closeSomarcasChoice" type="button">× Fechar</button></div><p>Escolha a modalidade que será copiada como <b>custo</b> para este orçamento. Todas as quatro opções continuam disponíveis na Biblioteca.</p>${somarcasPriceTable(prices)}<label class="c4u-somarcas-choose-label">Modalidade de custo<select id="somarcasMode"><option value="">Selecione uma modalidade</option>${choices.map(p=>`<option value="${p.key}">${esc(p.label)} — ${somarcasPriceText(prices[p.key])}</option>`).join('')}</select></label><label class="c4u-somarcas-choose-label">Quantidade<input id="somarcasQty" type="number" min="1" step="1" value="50"></label><p class="c4u-somarcas-warning">Preços informativos, sujeitos à confirmação com o fornecedor. Esta escolha não envia pedidos de compra.</p><div class="form-actions"><button type="button" class="btn btn-light" id="cancelSomarcasChoice">Cancelar</button><button type="button" class="btn btn-primary" id="confirmSomarcasChoice">Adicionar ao orçamento</button></div></div>`;
 document.body.appendChild(overlay);
 const close=()=>overlay.remove();$('#closeSomarcasChoice').onclick=close;$('#cancelSomarcasChoice').onclick=close;
 $('#confirmSomarcasChoice').onclick=()=>{
  const mode=$('#somarcasMode').value,qty=Number($('#somarcasQty').value),p=choices.find(x=>x.key===mode);
  if(!p)return toast('Escolha uma das quatro modalidades de preço.');
  if(!Number.isSafeInteger(qty)||qty<1)return toast('Informe uma quantidade inteira maior que zero.');
  const cost=Number(prices[mode]);
  window.qItems.push({...blankItem(),productName:item.name,description:item.description||item.name,qty,unitCost:cost,supplierCode:item.code,image:item.image||'',somarcasSnapshot:{source:'Só Marcas',code:item.code,priceMode:mode,priceModeLabel:p.label,costAtQuote:cost,allPrices:{...prices},stockAtQuote:item.stock,providerUpdatedAt:item.providerUpdatedAt||'',importedAt:item.lastSupplierSync||'',ordersToSupplier:false}});
  close();document.getElementById('libraryPicker')?.remove();paintItems();calcUI();toast('Só Marcas adicionada com o custo da modalidade escolhida.');
 };
 $('#somarcasMode').focus();
}

// Custo importado da SPOT: usa a faixa de maior quantidade mínima atendida; sem faixa, usa YourPrice.
// Não inventa custo nem aplica preço de uma faixa cuja quantidade mínima não foi atingida.
function spotCostForQuantity(pricing,qty){
 const quantity=Number(qty);if(!Number.isSafeInteger(quantity)||quantity<1)return null;
 let tier=null;
 for(const row of Array.isArray(pricing?.tiers)?pricing.tiers:[]){
  const min=Number(row?.minQty),value=Number(row?.supplierPrice);
  if(Number.isSafeInteger(min)&&min>0&&Number.isFinite(value)&&value>0&&quantity>=min&&(!tier||min>tier.minQty))tier={cost:value,minQty:min,source:'tier'};
 }
 if(tier)return tier;
 const base=pricing?.yourPrice;
 if(base===null||base===undefined||String(base).trim()==='')return null;
 const cost=Number(base);return Number.isFinite(cost)&&cost>0?{cost,minQty:null,source:'yourPrice'}:null;
}
// Apenas novos itens SPOT usam custo automático. Itens antigos e custos editados pelo usuário são preservados.
function spotSyncCost(item,qty,visibleCost){
 const snapshot=item?.spotSnapshot;if(!snapshot?.autoSupplierPrice)return {cost:visibleCost,snapshot};
 if(visibleCost!==Number(item.unitCost))return {cost:visibleCost,snapshot:{...snapshot,autoSupplierPrice:false}};
 if(qty===Number(item.qty))return {cost:visibleCost,snapshot};
 const selected=spotCostForQuantity(snapshot.pricing,qty);
 return {cost:selected?.cost??0,snapshot:{...snapshot,priceSource:selected?.source||null,priceMinQty:selected?.minQty??null}};
}
function openSpotQuoteItem(item){
 if(!item||!Array.isArray(window.qItems))return;
 let qty=50,selected=spotCostForQuantity(item.price,qty);
 if(!selected){const mins=(item.price?.tiers||[]).map(t=>Number(t.minQty)).filter(n=>Number.isSafeInteger(n)&&n>0).sort((a,b)=>a-b);if(mins.length){qty=mins[0];selected=spotCostForQuantity(item.price,qty)}}
 if(!selected)return toast('A SPOT não informou preço para este SKU. Atualize o catálogo.');
 window.qItems.push({...blankItem(),productName:item.name,description:item.description||item.name,qty,unitCost:selected.cost,supplierCode:item.sku,image:item.imageKind==='variacao'?(item.images?.[0]||''):'',spotSnapshot:{sku:item.sku,reference:item.reference,color:item.color,stockAtQuote:item.stock,stockCheckedAt:item.lastSupplierSync,pricing:{yourPrice:item.price?.yourPrice??null,tiers:(item.price?.tiers||[]).map(t=>({minQty:t.minQty,supplierPrice:t.supplierPrice}))},priceSource:selected.source,priceMinQty:selected.minQty,autoSupplierPrice:true,ordersToSupplier:false}});
 document.getElementById('libraryPicker')?.remove();paintItems();calcUI();toast('Produto SPOT adicionado com custo automático do fornecedor.');
}
function addLibraryItemToQuote(id){const p=cache.itemLibrary.find(x=>x.id===id);if(!p)return;const opts=(p.supplierOptions||[]).filter(x=>Number(x.supplierId)||Number(x.cost));const preferred=opts.slice().sort((a,b)=>(Number(a.cost)||999999)-(Number(b.cost)||999999))[0]||{};window.qItems.push({...blankItem(),libraryItemId:p.id,productName:p.name,description:p.commercialDescription||p.technicalDescription||p.name,image:p.images?.[0]||'',supplierId:Number(preferred.supplierId)||0,supplierCode:preferred.supplierCode||'',unitCost:Number(preferred.cost)||Number(p.cost)||0,qty:Math.max(1,Number(preferred.minQty)||Number(p.minQty)||50),librarySnapshot:{id:p.id,internalCode:p.internalCode,name:p.name,category:p.category,subcategory:p.subcategory,material:p.material,dimensions:p.dimensions,capacity:p.capacity,colors:p.colors,personalizationTypes:p.personalizationTypes,engravingArea:p.engravingArea,images:p.images,supplierOptions:p.supplierOptions}});document.getElementById('libraryPicker')?.remove();paintItems();calcUI();toast('Item copiado da Biblioteca')}

function addStockItemToQuote(id){const x=(cache.physicalStock||[]).find(v=>v.id===id);if(!x)return;const clientId=Number($('#qf [name="clientId"]')?.value||0);if(x.ownerClientId&&x.ownerClientId!==clientId)return toast('Este estoque pertence a outro cliente. Selecione o cliente proprietário.');window.qItems.push({...blankItem(),physicalStockId:x.id,libraryItemId:x.libraryItemId||0,productName:x.name,description:x.description||x.name,qty:Math.min(50,Number(x.available)||1),supplierCode:x.code,unitCost:x.cost||0,image:x.images?.[0]||''});document.getElementById('libraryPicker')?.remove();paintItems();calcUI();toast('Item físico adicionado ao orçamento. Saldo não é baixado automaticamente.')}
// HISTÓRICO DE DOCUMENTOS / VERSÕES
function pdfHistoryBlock(type,sourceId){const rows=cache.pdfHistory.filter(x=>x.type===type&&x.sourceId===Number(sourceId)).sort((a,b)=>b.version-a.version);return `<details class="details-block pdf-history"><summary>Histórico de PDFs (${rows.length})</summary><div class="details-content">${rows.length?rows.map(x=>`<div class="history-row"><div><b>Versão ${x.version}</b><small>${esc(x.templateName)} · ${dmy(x.createdAt)} · ${esc(x.createdBy||'')}</small></div><button type="button" class="btn btn-light btn-sm" onclick="printHistoricalPdf(${x.id})">Visualizar / PDF</button></div>`).join(''):'<div class="empty">Nenhuma versão gerada ainda.</div>'}</div></details>`}
function printHistoricalPdf(id){const h=cache.pdfHistory.find(x=>x.id===id);if(!h)return;printDoc(`${h.sourceNumber} - Versão ${h.version}`,h.html)}
function dynamicText(text,data){return String(text||'').replace(/\{\{([a-zA-Z0-9_]+)\}\}/g,(_,k)=>String(data[k]??''))}
function quoteTemplateFor(id){const all=cache.documentTemplates.filter(x=>x.type==='quote'&&x.active!==false);return all.find(x=>x.id===Number(id))||all.find(x=>x.isDefault)||all[0]||{}}
function invoiceTemplateFor(id){const all=cache.documentTemplates.filter(x=>x.type==='invoice'&&x.active!==false);return all.find(x=>x.id===Number(id))||all.find(x=>x.isDefault)||all[0]||{}}
function chooseTemplate(type,cb){const all=cache.documentTemplates.filter(x=>x.type===type&&x.active!==false);if(!all.length)return cb(type==='quote'?quoteTemplateFor():invoiceTemplateFor());const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='templateChooser';overlay.innerHTML=`<div class="modal-card template-chooser"><div class="page-head"><div><h2>Escolha o modelo</h2><p>${type==='quote'?'Máscara de Orçamento':'Pré-Nota'} será gerada usando este visual.</p></div><button class="btn btn-light" onclick="document.getElementById('templateChooser').remove()">×</button></div><div class="template-choice-list">${all.map(t=>`<button onclick="selectTemplateAndContinue(${t.id})"><span><b>${esc(t.name)}</b><small>${t.isDefault?'Modelo padrão':'Modelo alternativo'}</small></span><strong>Usar</strong></button>`).join('')}</div></div>`;document.body.appendChild(overlay);window._templateContinue=cb;window._templateType=type}
function selectTemplateAndContinue(id){const t=cache.documentTemplates.find(x=>x.id===id);document.getElementById('templateChooser')?.remove();const cb=window._templateContinue;window._templateContinue=null;if(cb)cb(t)}
async function generateQuotePdf(id){const q=cache.quotes.find(x=>x.id===id);if(!q)return;chooseTemplate('quote',async t=>{const html=quotePrintHtml(q,t);try{const row=await api('/api/pdfHistory/version',{method:'POST',body:JSON.stringify({type:'quote',sourceId:q.id,sourceNumber:q.number,templateId:t.id||0,templateName:t.name||'Padrão',html,snapshot:q})});cache.pdfHistory.push(row);printDoc(`Orçamento ${q.number} - v${row.version}`,html)}catch(e){toast(e.message)}})}

