function templateForm(type,id){const t=cache.documentTemplates.find(x=>x.id===id)||{type,name:type==='quote'?'Novo modelo de orçamento':'Novo modelo de Pré-Nota',active:true,accent:type==='quote'?'#6f2dbd':'#394150',headerBg:'#f3eafd',clientColor:'#2f123f',clientNameSize:34,showCompany:true,showImages:true,showSeller:true,showPayment:true,showUnitPrice:true,showDocument:true,showPhone:true,showEmail:true,showDelivery:true,imageSize:'medium',title:type==='quote'?'PROPOSTA COMERCIAL':'PRÉ-NOTA',subtitle:type==='quote'?'Soluções personalizadas para sua empresa':'',warningText:'DOCUMENTO INTERNO • SEM VALOR FISCAL',introText:'Olá {{cliente}}, preparamos esta proposta especialmente para sua necessidade.',footer:type==='quote'?'Obrigado pela oportunidade. Estamos à disposição.':'Documento interno para conferência. Não substitui NF-e, DANFE ou documento fiscal autorizado pela SEFAZ.'};content.innerHTML=`<div class="card page-card template-editor-page">${back(id?'Editar modelo':'Novo modelo',type==='quote'?'Máscara de Orçamento':'Pré-Nota')}<div class="template-editor-grid"><form id="templateForm" class="form"><div class="form-grid">${field('Nome do modelo','name',t.name||'','required')}${select('Status','active',t.active===false?'false':'true',[['true','Ativo'],['false','Inativo']])}${field('Cor principal','accent',t.accent||'',"type='color'")}${field('Título','title',t.title||'')}${type==='quote'?field('Subtítulo','subtitle',t.subtitle||''):field('Aviso legal superior','warningText',t.warningText||'')}</div>${type==='quote'?`${textarea('Texto de abertura — aceita campos {{...}}','introText',t.introText||'')}${field('Cor do fundo do cabeçalho','headerBg',t.headerBg||'#f3eafd',"type='color'")}${field('Cor do nome do cliente','clientColor',t.clientColor||'#2f123f',"type='color'")}${field('Tamanho do nome do cliente','clientNameSize',t.clientNameSize||34,"type='number' min='20' max='60'")}${select('Tamanho das imagens','imageSize',t.imageSize||'medium',[['small','Pequena'],['medium','Média'],['large','Grande']])}${select('Ordem das seções','sectionOrder',t.sectionOrder||'client_items_terms',[['client_items_terms','Cliente → Itens → Condições'],['client_terms_items','Cliente → Condições → Itens'],['items_client_terms','Itens → Cliente → Condições']])}`:''}<div class="toggle-grid">${checkboxField('Mostrar logo','showLogo',t.showLogo!==false)}${checkboxField('Mostrar empresa','showCompany',t.showCompany!==false)}${type==='quote'?checkboxField('Mostrar imagens','showImages',t.showImages!==false):''}${checkboxField('Mostrar vendedor','showSeller',t.showSeller!==false)}${checkboxField('Mostrar pagamento','showPayment',t.showPayment!==false)}${type==='quote'?checkboxField('Mostrar valor unitário','showUnitPrice',t.showUnitPrice!==false):checkboxField('Mostrar entrega','showDelivery',t.showDelivery!==false)}${checkboxField('Mostrar CNPJ/CPF','showDocument',t.showDocument!==false)}${checkboxField('Mostrar telefone','showPhone',t.showPhone!==false)}${checkboxField('Mostrar e-mail','showEmail',t.showEmail!==false)}</div>${textarea('Rodapé — aceita campos {{...}}','footer',t.footer||'')}<div class="form-actions"><button class="btn btn-primary">Salvar modelo</button></div></form><div class="template-preview-panel"><div class="preview-label">PRÉ-VISUALIZAÇÃO A4</div><div id="templatePreview" class="template-preview"></div></div></div></div>`;
 const f=$('#templateForm');const redraw=()=>renderTemplatePreview(type,Object.fromEntries(new FormData(f)),f);f.oninput=redraw;f.onchange=redraw;f.onsubmit=async e=>{e.preventDefault();const fd=new FormData(f),d=Object.fromEntries(fd);d.type=type;d.active=d.active==='true';['showLogo','showCompany','showImages','showSeller','showPayment','showUnitPrice','showDelivery','showDocument','showPhone','showEmail'].forEach(k=>d[k]=fd.has(k));d.clientNameSize=Number(d.clientNameSize||34);await api(id?`/api/documentTemplates/${id}`:'/api/documentTemplates',{method:id?'PUT':'POST',body:JSON.stringify(d)});toast('Modelo salvo');loadPage('editables')};redraw()}
function renderTemplatePreview(type,d,f){const b=$('#templatePreview');if(!b)return;const sample={id:0,number:type==='quote'?'ORC-00125':'PN-00042',createdAt:new Date().toISOString(),validUntil:new Date(Date.now()+7*864e5).toISOString().slice(0,10),deliveryDeadline:new Date(Date.now()+12*864e5).toISOString().slice(0,10),clientSnapshot:{company:'Cliente Demonstração Ltda',document:'12.345.678/0001-90',phone:'(11) 99999-9999',email:'contato@cliente.com',address:'Av. Exemplo, 100 - São Paulo/SP'},salesperson:'Jorge Cauã',paymentData:'50% no fechamento + saldo',items:[{productName:'Garrafa Térmica Personalizada',description:'Gravação a laser',qty:50,unitPrice:38.4,grossTotal:1920,image:''}],total:1920,notes:'Prazo sujeito à aprovação da arte.'};const bool=k=>f?new FormData(f).has(k):true;const tpl={...d,showLogo:bool('showLogo'),showCompany:bool('showCompany'),showImages:bool('showImages'),showSeller:bool('showSeller'),showPayment:bool('showPayment'),showUnitPrice:bool('showUnitPrice'),showDelivery:bool('showDelivery'),showDocument:bool('showDocument'),showPhone:bool('showPhone'),showEmail:bool('showEmail')};b.innerHTML=type==='quote'?quotePrintHtml(sample,tpl):invoicePrintHtml(sample,tpl)}
