function renderInvoices(list=cache.invoices){content.innerHTML=`<div class="card panel prenote-info"><b>Pré-Notas</b><span>Documento administrativo interno, independente da Máscara de Orçamento.</span><small>Não é NF-e nem DANFE e não possui valor fiscal.</small></div>${toolbar('Nova Pré-Nota','invoiceForm()')}<div class="table-wrap"><table><thead><tr><th>Pré-Nota</th><th>Pedido</th><th>Cliente</th><th>Emissão</th><th>Total</th><th>Status</th><th>Ações</th></tr></thead><tbody>${list.map(i=>{const o=cache.orders.find(o=>o.id===i.orderId);return `<tr><td><b>${esc(i.number)}</b></td><td>${o?.number||'Manual'}</td><td>${esc(i.clientSnapshot?.company||i.clientSnapshot?.name||clientName(i.clientId))}</td><td>${dmy(i.createdAt)}</td><td>${brl(i.total)}</td><td>${badge(i.status)}</td><td class="actions"><button class="btn btn-light btn-sm" onclick="invoiceForm(${i.id})">Abrir</button><button class="btn btn-primary btn-sm" onclick="printInvoice(${i.id})">Gerar PDF</button><button class="btn btn-light btn-sm" onclick="duplicateInvoice(${i.id})">Duplicar</button><button class="btn btn-danger btn-sm" onclick="del('invoices',${i.id},'invoices')">Excluir</button></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">Nenhuma Pré-Nota criada.</td></tr>'}</tbody></table></div>`;bindSearch(cache.invoices,renderInvoices)}
