function blankInvoiceItem(){return {code:'',description:'',qty:1,unitPrice:0,grossTotal:0}}
function invoiceForm(id){const i=cache.invoices.find(x=>x.id===id)||{};window.invItems=(i.items||[]).map(x=>({code:x.code||x.supplierCode||x.librarySnapshot?.internalCode||'',description:x.productName||x.description||'',qty:Number(x.qty)||1,unitPrice:Number(x.unitPrice)||0,grossTotal:Number(x.grossTotal)||Number(x.qty||1)*Number(x.unitPrice||0)}));if(!window.invItems.length)window.invItems=[blankInvoiceItem()];const c=i.clientSnapshot||{};content.innerHTML=`<div class="card page-card">${back(id?`Pré-Nota ${i.number}`:'Nova Pré-Nota','Documento formal e administrativo')}<form id="invoiceForm" class="form"><div class="section-title">Origem e controle</div><div class="form-grid">${select('Pedido relacionado','orderId',i.orderId||'',[['','Pré-Nota manual'],...cache.orders.map(o=>[o.id,`${o.number} — ${o.clientSnapshot?.company||clientName(o.clientId)}`])])}${select('Orçamento relacionado','quoteId',i.quoteId||'',[['','Nenhum'],...cache.quotes.map(q=>[q.id,`${q.number} — ${q.clientSnapshot?.company||clientName(q.clientId)}`])])}${select('Status','status',i.status||'draft',[['draft','Rascunho'],['sent','Enviada'],['approved','Aprovada'],['cancelled','Cancelada']])}${field('Natureza / finalidade','nature',i.nature||'Pré-Nota comercial interna')}${select('Vendedor','salesperson',i.salesperson||'',[['','Selecione...'],...cache.users.filter(u=>u.active!==false).map(u=>[u.name,u.name])])}</div><div class="form-actions compact"><button type="button" class="btn btn-light" onclick="loadOrderIntoInvoice()">Carregar dados do pedido selecionado</button></div>
 <div class="section-title">Cliente / destinatário</div><div class="form-grid">${select('Cliente cadastrado','clientId',i.clientId||'',[['','Selecionar / preencher manualmente'],...cache.clients.map(c=>[c.id,c.name||c.company])])}${field('Razão Social / Nome','company',c.company||c.name||'')}${field('CNPJ/CPF','document',c.document||'')}${field('Inscrição Estadual','ie',c.ie||'')}${field('Telefone','phone',c.phone||'')}${field('E-mail','email',c.email||'')}${field('Endereço','address',c.address||'','', 'span2')}${field('Número','addressNumber',c.addressNumber||'')}${field('Bairro','district',c.district||'')}${field('Cidade','city',c.city||'')}${field('UF','state',c.state||'')}${field('CEP','zipCode',c.zipCode||'')}</div>
 <div class="section-title">Itens da Pré-Nota</div><div id="invoiceItems"></div><button type="button" class="btn btn-light" onclick="addInvoiceItem()">+ Adicionar item</button>
 <div class="section-title">Valores e condições</div><div class="form-grid">${field('Frete','freight',i.freight||0,"type='number' min='0' step='0.01'")}${field('Desconto','discount',i.discount||0,"type='number' min='0' step='0.01'")}${field('Impostos / acréscimos','taxes',i.taxes||0,"type='number' min='0' step='0.01'")}${field('Vencimento','paymentDueDate',i.paymentDueDate||'',"type='date'")}${field('Prazo de entrega','deliveryDeadline',i.deliveryDeadline||'',"type='date'")}${field('Endereço de entrega','deliveryAddress',i.deliveryAddress||'','', 'span2')}</div>${textarea('Forma / condição de pagamento','paymentData',i.paymentData||'')}${textarea('Informações complementares / observações','notes',i.notes||'')}<div id="invoiceTotals"></div>${id?pdfHistoryBlock('invoice',id):''}<div class="form-actions"><button type="button" class="btn btn-light" onclick="loadPage('invoices')">Cancelar</button><button class="btn btn-primary">Salvar Pré-Nota</button>${id?`<button type="button" class="btn btn-success" onclick="printInvoice(${id})">Gerar PDF</button>`:''}</div></form></div>`;paintInvoiceItems();invoiceCalc();$('#invoiceForm [name="clientId"]').onchange=e=>fillInvoiceClient(Number(e.target.value));$('#invoiceForm').oninput=e=>{if(e.target.closest('#invoiceItems')||['freight','discount','taxes'].includes(e.target.name))invoiceCalc()};$('#invoiceForm').onsubmit=async e=>{e.preventDefault();syncInvoiceItems();const fd=new FormData(e.target),d=Object.fromEntries(fd);d.orderId=Number(d.orderId)||0;d.quoteId=Number(d.quoteId)||0;d.clientId=Number(d.clientId)||0;d.clientSnapshot={company:d.company,document:d.document,ie:d.ie,phone:d.phone,email:d.email,address:d.address,addressNumber:d.addressNumber,district:d.district,city:d.city,state:d.state,zipCode:d.zipCode};['company','document','ie','phone','email','address','addressNumber','district','city','state','zipCode'].forEach(k=>delete d[k]);d.items=window.invItems;d.subtotal=window.invItems.reduce((s,x)=>s+Number(x.grossTotal||0),0);d.freight=Number(d.freight||0);d.discount=Number(d.discount||0);d.taxes=Number(d.taxes||0);d.total=d.subtotal+d.freight+d.taxes-d.discount;const saved=await api(id?`/api/invoices/${id}`:'/api/invoices',{method:id?'PUT':'POST',body:JSON.stringify(d)});toast('Pré-Nota salva');await refresh();invoiceForm(saved.id)} }
function fillInvoiceClient(id){const c=cache.clients.find(x=>x.id===id);if(!c)return;['company','document','ie','phone','email','address','addressNumber','district','city','state','zipCode'].forEach(k=>{const el=$(`#invoiceForm [name="${k}"]`);if(el)el.value=c[k]||((k==='company')?c.name:'')})}
function loadOrderIntoInvoice(){const id=Number($('#invoiceForm [name="orderId"]')?.value)||0,o=cache.orders.find(x=>x.id===id);if(!o)return toast('Selecione um pedido');const c=o.clientSnapshot||{};$('#invoiceForm [name="clientId"]').value=o.clientId||'';['company','document','ie','phone','email','address','addressNumber','district','city','state','zipCode'].forEach(k=>{const el=$(`#invoiceForm [name="${k}"]`);if(el)el.value=c[k]||((k==='company')?c.name:'')});if($('#invoiceForm [name="quoteId"]'))$('#invoiceForm [name="quoteId"]').value=o.quoteId||'';$('#invoiceForm [name="salesperson"]').value=o.salesperson||'';$('#invoiceForm [name="paymentDueDate"]').value=o.paymentDueDate||'';$('#invoiceForm [name="deliveryDeadline"]').value=o.deliveryDeadline||'';$('#invoiceForm [name="paymentData"]').value=o.paymentData||'';$('#invoiceForm [name="deliveryAddress"]').value=[c.address,c.addressNumber,c.district,c.city,c.state].filter(Boolean).join(', ');window.invItems=(o.items||[]).map(x=>({code:x.supplierCode||x.librarySnapshot?.internalCode||'',description:x.productName||x.description||'',qty:Number(x.qty)||1,unitPrice:Number(x.unitPrice)||0,grossTotal:Number(x.grossTotal)||Number(x.qty||1)*Number(x.unitPrice||0)}));if(!window.invItems.length)window.invItems=[blankInvoiceItem()];paintInvoiceItems();invoiceCalc();toast('Dados do pedido carregados')}
function addInvoiceItem(){syncInvoiceItems();window.invItems.push(blankInvoiceItem());paintInvoiceItems();invoiceCalc()}
function removeInvoiceItem(i){syncInvoiceItems();if(window.invItems.length<=1)return;window.invItems.splice(i,1);paintInvoiceItems();invoiceCalc()}
function syncInvoiceItems(){$$('.invoice-item-row').forEach((r,i)=>{const qty=Number($('[name="qty"]',r)?.value)||1,unit=Number($('[name="unitPrice"]',r)?.value)||0;window.invItems[i]={code:$('[name="code"]',r)?.value||'',description:$('[name="description"]',r)?.value||'',qty,unitPrice:unit,grossTotal:qty*unit}})}
function paintInvoiceItems(){const b=$('#invoiceItems');if(!b)return;b.innerHTML=window.invItems.map((x,i)=>`<div class="invoice-item-row">${field('Código','code',x.code||'')}${field('Descrição','description',x.description||'')}${field('Qtd.','qty',x.qty||1,"type='number' min='1'")}${field('Valor unitário','unitPrice',x.unitPrice||0,"type='number' min='0' step='0.01'")}<div class="invoice-line-total"><small>Total</small><b>${brl(Number(x.qty||1)*Number(x.unitPrice||0))}</b></div><button type="button" class="btn btn-danger btn-sm" onclick="removeInvoiceItem(${i})">×</button></div>`).join('')}
function invoiceCalc(){syncInvoiceItems();const subtotal=window.invItems.reduce((s,x)=>s+Number(x.grossTotal||0),0),freight=Number($('#invoiceForm [name="freight"]')?.value||0),discount=Number($('#invoiceForm [name="discount"]')?.value||0),taxes=Number($('#invoiceForm [name="taxes"]')?.value||0),total=subtotal+freight+taxes-discount;const b=$('#invoiceTotals');if(b)b.innerHTML=`<div class="summary"><div class="calc"><small>Subtotal</small><b>${brl(subtotal)}</b></div><div class="calc"><small>Frete</small><b>${brl(freight)}</b></div><div class="calc"><small>Impostos / acréscimos</small><b>${brl(taxes)}</b></div><div class="calc"><small>Desconto</small><b>${brl(discount)}</b></div><div class="calc total"><small>Total da Pré-Nota</small><b>${brl(total)}</b></div></div>`}
async function duplicateInvoice(id){try{const x=await api(`/api/invoices/${id}/duplicate`,{method:'POST',body:'{}'});toast('Pré-Nota duplicada');await refresh();invoiceForm(x.id)}catch(e){toast(e.message)}}
function printInvoice(id){const i=cache.invoices.find(x=>x.id===id);if(!i)return;chooseTemplate('invoice',async t=>{const html=invoicePrintHtml(i,t);try{const row=await api('/api/pdfHistory/version',{method:'POST',body:JSON.stringify({type:'invoice',sourceId:i.id,sourceNumber:i.number,templateId:t.id||0,templateName:t.name||'Padrão',html,snapshot:i})});cache.pdfHistory.push(row);printDoc(`Pré-Nota ${i.number} - v${row.version}`,html)}catch(e){toast(e.message)}})}

// Ajuste da Busca Global para Biblioteca
async function openGlobalSearchResult(kind,id){const cfg={client:['clients',clientForm],supplier:['suppliers',supplierForm],product:['products',productForm],libraryItem:['itemLibrary',libraryItemForm],quote:['quotes',quoteForm],order:['orders',orderForm],invoice:['invoices',invoiceForm],finance:['finance',financeForm],activity:['crm',null],document:['documents',documentForm]};if(!cfg[kind])return;await loadPage(cfg[kind][0]);if(kind==='activity'){const a=cache.activities.find(x=>x.id===id);return activityForm(a?.clientId,id)}cfg[kind][1]?.(id)}

// Configurações de empresa necessárias para documentos formais
async function renderSettings(){
 settings=await api('/api/settings');
 let net={urls:[],localUrl:'http://localhost:3000',host:'',port:3000};try{net=await api('/api/network-info')}catch{}
 content.innerHTML=`<div class="card page-card"><div class="page-head"><div><h2>Configurações gerais</h2><p><button type="button" class="btn btn-light" onclick="loadPage('profile')">Meu perfil →</button></p><p>Dados da empresa usados no sistema, Máscara de Orçamento e Pré-Notas.</p></div></div><form id="settingsForm" class="form"><div class="section-title">Empresa / Emitente</div><div class="form-grid">${field('Nome do sistema','systemName',settings.systemName)}${field('Nome fantasia','companyName',settings.companyName)}${field('Razão Social','companyLegalName',settings.companyLegalName||'')}${field('CNPJ','companyDocument',settings.companyDocument||'')}${field('Inscrição Estadual','companyIE',settings.companyIE||'')}${field('Telefone','companyPhone',settings.companyPhone||'')}${field('E-mail','companyEmail',settings.companyEmail||'')}${field('Endereço','companyAddress',settings.companyAddress||'','', 'span2')}${field('Cidade','companyCity',settings.companyCity||'')}${field('UF','companyState',settings.companyState||'')}${field('CEP','companyZipCode',settings.companyZipCode||'')}</div><div class="section-title">Identidade</div><div class="form-grid">${field('Cor principal','primaryColor',settings.primaryColor,"type='color'")}${field('Cor de contraste','contrastColor',settings.contrastColor,"type='color'")}${field('Símbolo / letra quando não houver logo','quoteLogoText',settings.quoteLogoText||'T')}<div class="field"><label>Logo da empresa</label><input id="companyLogoFile" type="file" accept="image/*"><small>${settings.companyLogo?'Logo cadastrada. Escolha outro arquivo para substituir.':'PNG/JPG recomendado.'}</small></div></div>${settings.companyLogo?`<div class="company-logo-preview"><img src="${settings.companyLogo}"><button type="button" class="btn btn-light btn-sm" id="removeCompanyLogo">Remover logo</button></div>`:''}<div class="form-actions"><button class="btn btn-primary">Salvar configurações</button></div></form></div>
 <div class="network-card"><div class="network-status"><span class="network-status-dot"></span><b>Rede local ativa</b></div><h3>Acesso por outros computadores</h3><p class="muted">O C4U desta máquina está preparado para compartilhar a mesma base de dados com uma pequena equipe na mesma rede local.</p>${(net.urls||[]).length?(net.urls||[]).map(u=>`<div class="network-url"><code>${esc(u)}</code><button class="btn btn-light btn-sm" type="button" data-copy-url="${esc(u)}">Copiar</button></div>`).join(''):`<div class="network-url"><code>${esc(net.localUrl||'http://localhost:3000')}</code></div>`}<div class="network-help">Computador servidor: <b>${esc(net.host||'esta máquina')}</b>. Para os outros computadores funcionarem, esta máquina precisa permanecer ligada, com o C4U aberto e conectada à mesma rede. Execute uma vez o arquivo <b>CONFIGURAR REDE LOCAL.bat</b> como administrador do Windows para liberar a porta 3000 no Firewall.</div></div><div class="network-card"><h3>Usuários e máquinas online</h3><p class="muted">A luz fica verde enquanto o usuário está conectado e vermelha quando estiver offline.</p><div id="presencePanel"><div class="empty">Carregando presença...</div></div></div>`;
 try{updatePresencePanel(await api('/api/presence'))}catch{};if(me?.role==='Administrador'){const accessBox=document.createElement('div');accessBox.innerHTML=await renderAccessControlBlock();content.appendChild(accessBox);bindAccessControl();const box=document.createElement('div');box.innerHTML=await renderBackupsBlock();content.appendChild(box);$('#backupNow').onclick=async()=>{await api('/api/backups',{method:'POST',body:'{}'});toast('Backup criado');renderSettings()};$$('[data-restore-backup]').forEach(b=>b.onclick=async()=>{if(await C4UDialog.confirm('Restaurar este backup?')){await api('/api/backups/restore',{method:'POST',body:JSON.stringify({name:b.dataset.restoreBackup})});toast('Backup restaurado');location.reload()}})}
 let logo=settings.companyLogo||'';$('#companyLogoFile').onchange=e=>{const f=e.target.files[0];if(f)readFileData(f,d=>logo=d)};if($('#removeCompanyLogo'))$('#removeCompanyLogo').onclick=()=>{logo='';toast('Logo será removida ao salvar')};$$('[data-copy-url]').forEach(b=>b.onclick=()=>navigator.clipboard?.writeText(b.dataset.copyUrl).then(()=>toast('Endereço copiado')));$('#settingsForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));delete d.companyLogoFile;d.companyLogo=logo;settings=await api('/api/settings',{method:'PUT',body:JSON.stringify(d)});applySettings();toast('Configurações salvas')}
}



function taskForm(id){const t=cache.tasks.find(x=>x.id===id)||{status:'pending',priority:'normal',assignedUserId:me?.id||0,dueDate:new Date().toISOString().slice(0,10)};content.innerHTML=`<div class="card page-card">${back(id?'Editar tarefa':'Nova tarefa','Responsabilidade da equipe')}<form id="taskForm" class="form"><div class="form-grid">${field('Título *','title',t.title||'','required')}${select('Responsável','assignedUserId',t.assignedUserId||'',cache.users.filter(u=>u.active!==false).map(u=>[u.id,u.name]))}${field('Prazo','dueDate',t.dueDate||'',"type='date'")}${select('Prioridade','priority',t.priority||'normal',[['low','Baixa'],['normal','Normal'],['high','Alta'],['urgent','Urgente']])}${select('Status','status',t.status||'pending',[['pending','Pendente'],['doing','Em andamento'],['done','Concluída']])}${select('Cliente','clientId',t.clientId||'',[['','Nenhum'],...cache.clients.map(c=>[c.id,c.company||c.name])])}</div>${textarea('Descrição','notes',t.notes||'','span3')}<div class="form-actions"><button class="btn btn-primary">Salvar tarefa</button></div></form></div>`;$('#taskForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.assignedUserId=Number(d.assignedUserId)||0;d.clientId=Number(d.clientId)||0;await api(id?`/api/tasks/${id}`:'/api/tasks',{method:id?'PUT':'POST',body:JSON.stringify(d)});await refresh();toast('Tarefa salva');renderTasks()}}
function renderTasks(list=cache.tasks){const visible=me?.role==='Administrador'?list:list.filter(t=>!t.assignedUserId||t.assignedUserId===me?.id);content.innerHTML=toolbar('Nova tarefa','taskForm()')+`<div class="table-wrap"><table><thead><tr><th>Tarefa</th><th>Responsável</th><th>Prazo</th><th>Prioridade</th><th>Status</th><th>Ações</th></tr></thead><tbody>${visible.map(t=>`<tr><td><b>${esc(t.title)}</b><br><small>${esc(t.notes||'')}</small></td><td>${esc(userName(t.assignedUserId))}</td><td>${dmy(t.dueDate)}</td><td>${esc(t.priority||'normal')}</td><td>${esc(t.status||'pending')}</td><td><button class="btn btn-light btn-sm" onclick="taskForm(${t.id})">Editar</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nenhuma tarefa.</td></tr>'}</tbody></table></div>`;bindSearch(visible,renderTasks)}
async function renderNotifications(){const rows=await api('/api/notifications');content.innerHTML=`<div class="page-head"><div><h2>Notificações</h2><p>Avisos e movimentações importantes.</p></div><button class="btn btn-light" id="readAll">Marcar todas como lidas</button></div><div class="card panel">${rows.map(n=>`<div class="alert ${n.read?'':'notification-unread'}"><b>${esc(n.title)}</b> — ${esc(n.message||'')} <small>${new Date(n.createdAt).toLocaleString('pt-BR')}</small></div>`).join('')||'<div class="empty">Nenhuma notificação.</div>'}</div>`;$('#readAll').onclick=async()=>{await api('/api/notifications/read-all',{method:'POST',body:'{}'});renderNotifications()}}
async function renderActivityLog(){const rows=await api('/api/audit');content.innerHTML=`<div class="card panel"><h3>Histórico de ações</h3><div class="table-wrap"><table><thead><tr><th>Data</th><th>Usuário</th><th>Ação</th><th>Módulo</th><th>Registro</th><th>Detalhe</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${new Date(a.createdAt).toLocaleString('pt-BR')}</td><td><b>${esc(a.userName)}</b></td><td>${esc(a.action)}</td><td>${esc(a.entity)}</td><td>${a.entityId||'—'}</td><td>${esc(a.detail||'')}</td></tr>`).join('')}</tbody></table></div></div>`}
async function renderAccessControlBlock(){const [reqs,devices]=await Promise.all([api('/api/access-requests'),api('/api/trusted-devices')]);const pending=reqs.filter(r=>r.status==='pending');return `<div class="network-card"><div class="page-head"><div><h3>Liberação sem login</h3><p>Um computador pode solicitar acesso na tela de login. Você aprova aqui e escolhe qual usuário será usado automaticamente.</p></div></div><div class="section-title">Solicitações pendentes</div>${pending.map(r=>`<div class="access-request-row"><div><b>${esc(r.deviceName||'Computador')}</b><small>${esc(r.ip||'')} • ${new Date(r.createdAt).toLocaleString('pt-BR')}</small></div><select data-access-user="${r.id}">${cache.users.filter(u=>u.active!==false).map(u=>`<option value="${u.id}">${esc(u.name)} — ${esc(u.login||'')}</option>`).join('')}</select><button class="btn btn-primary btn-sm" data-approve-access="${r.id}">Liberar sem login</button><button class="btn btn-light btn-sm" data-reject-access="${r.id}">Recusar</button></div>`).join('')||'<div class="empty">Nenhuma solicitação pendente.</div>'}<div class="section-title">Computadores já liberados</div>${devices.map(d=>`<div class="access-request-row"><div><b>${esc(d.deviceName||'Computador')}</b><small>${esc(d.userName||'')} • ${esc(d.lastIp||'')} ${d.lastUsedAt?`• último uso ${new Date(d.lastUsedAt).toLocaleString('pt-BR')}`:''}</small></div><span class="badge green">Sem login</span><button class="btn btn-danger btn-sm" data-revoke-device="${d.id}">Revogar</button></div>`).join('')||'<div class="empty">Nenhum computador liberado sem login.</div>'}</div>`}
function bindAccessControl(){$$('[data-approve-access]').forEach(b=>b.onclick=async()=>{const id=Number(b.dataset.approveAccess),sel=$(`[data-access-user="${id}"]`);await api(`/api/access-requests/${id}/approve`,{method:'POST',body:JSON.stringify({userId:Number(sel?.value)||0})});toast('Computador liberado sem login');renderSettings()});$$('[data-reject-access]').forEach(b=>b.onclick=async()=>{await api(`/api/access-requests/${b.dataset.rejectAccess}`,{method:'DELETE'});toast('Solicitação removida');renderSettings()});$$('[data-revoke-device]').forEach(b=>b.onclick=async()=>{if(!await C4UDialog.confirm('Revogar o acesso automático deste computador?'))return;await api(`/api/trusted-devices/${b.dataset.revokeDevice}`,{method:'DELETE'});toast('Acesso automático revogado');renderSettings()})}
async function renderBackupsBlock(){const rows=await api('/api/backups');return `<div class="network-card"><div class="page-head"><div><h3>Backups automáticos</h3><p>Até 30 cópias da base. Uma cópia diária é criada automaticamente.</p></div><button class="btn btn-primary" id="backupNow">Criar backup agora</button></div><div class="table-wrap"><table><thead><tr><th>Arquivo</th><th>Data</th><th>Tamanho</th><th></th></tr></thead><tbody>${rows.slice(0,12).map(b=>`<tr><td>${esc(b.name)}</td><td>${new Date(b.createdAt).toLocaleString('pt-BR')}</td><td>${Math.round(b.size/1024)} KB</td><td><button class="btn btn-light btn-sm" data-restore-backup="${esc(b.name)}">Restaurar</button></td></tr>`).join('')}</tbody></table></div></div>`}
async function showVersions(collection,id){const rows=await api(`/api/versions/${collection}/${id}`);content.innerHTML=`<div class="card page-card">${back('Histórico de versões',`${collection} #${id}`)}${rows.map(v=>`<div class="alert"><b>${new Date(v.createdAt).toLocaleString('pt-BR')} • ${esc(v.userName)}</b> — ${esc(v.action)} ${me?.role==='Administrador'?`<button class="btn btn-light btn-sm" onclick="restoreVersion(${v.id},'${collection}',${id})">Restaurar</button>`:''}</div>`).join('')||'<div class="empty">Ainda não existem versões anteriores.</div>'}</div>`}
async function restoreVersion(versionId,collection,id){if(!await C4UDialog.confirm('Restaurar esta versão? O estado atual também será preservado no histórico.'))return;await api(`/api/versions/${versionId}/restore`,{method:'POST',body:'{}'});await refresh();toast('Versão restaurada');showVersions(collection,id)}

// Versão final do layout comercial com ordem de seções configurável e logo
function quotePrintHtml(q,tpl){const s=tpl||quoteTemplateFor(),c=q.clientSnapshot||{};const tokens={cliente:c.company||c.name||clientName(q.clientId),numero_orcamento:q.number,vendedor:q.salesperson||'',data:dmy(q.createdAt),total:brl(q.total),prazo:dmy(q.deliveryDeadline),validade:dmy(q.validUntil),empresa:settings.companyName||'Toca dos Brindes'};const imgSize={small:45,medium:70,large:105}[s.imageSize||'medium'];const logo=s.showLogo===false?'':(settings.companyLogo?`<img src="${settings.companyLogo}" class="proposal-logo-img">`:`<div class="proposal-logo">${esc(settings.quoteLogoText||'T')}</div>`);const head=`<div class="proposal-head">${logo}<div><h1>${esc(s.title||'PROPOSTA COMERCIAL')}</h1><small>${esc(s.subtitle||'')}</small></div><div><b>${esc(q.number)}</b><br>Data: ${dmy(q.createdAt)}<br>Validade: ${dmy(q.validUntil)}</div></div>${s.showCompany!==false?`<div class="proposal-company">${esc(settings.companyName||'Toca dos Brindes')}</div>`:''}`;const client=`<section class="proposal-section"><div class="proposal-client" style="font-size:${Number(s.clientNameSize||34)}px">${esc(tokens.cliente)}</div><p class="proposal-intro">${esc(dynamicText(s.introText||'',tokens))}</p><div class="client-inline">${s.showDocument!==false?`<span><b>CNPJ/CPF</b>${esc(c.document||'—')}</span>`:''}${s.showPhone!==false?`<span><b>Telefone</b>${esc(c.phone||'—')}</span>`:''}${s.showEmail!==false?`<span><b>E-mail</b>${esc(c.email||'—')}</span>`:''}</div>${s.showSeller!==false?`<p><b>Consultor:</b> ${esc(q.salesperson||'—')}</p>`:''}</section>`;const items=`<section class="proposal-section"><table class="print-table"><thead><tr>${s.showImages!==false?'<th>Imagem</th>':''}<th>Item</th><th>Qtd.</th>${s.showUnitPrice!==false?'<th>Valor unit.</th>':''}<th>Total</th></tr></thead><tbody>${(q.items||[]).map(i=>`<tr>${s.showImages!==false?`<td>${i.image?`<img src="${i.image}" style="width:${imgSize}px;height:${imgSize}px;object-fit:contain">`:''}</td>`:''}<td><b>${esc(i.productName||i.description||'Item')}</b><br><small>${esc(i.description||'')}</small>${i.librarySnapshot?.internalCode?`<br><small>Cód. ${esc(i.librarySnapshot.internalCode)}</small>`:''}</td><td>${i.qty}</td>${s.showUnitPrice!==false?`<td>${brl(i.unitPrice)}</td>`:''}<td>${brl(i.grossTotal)}</td></tr>`).join('')}</tbody></table><div class="proposal-total-box"><span>VALOR TOTAL DA PROPOSTA</span><b>${brl(q.total)}</b></div></section>`;const terms=`<section class="proposal-section proposal-terms">${s.showPayment!==false?`<p><b>Pagamento:</b> ${esc(q.paymentData||'—')}</p>`:''}<p><b>Prazo:</b> ${dmy(q.deliveryDeadline)}</p><p>${esc(q.notes||'')}</p></section>`;const orders={client_items_terms:[client,items,terms],client_terms_items:[client,terms,items],items_client_terms:[items,client,terms]};const body=(orders[s.sectionOrder]||orders.client_items_terms).join('');return `<div class="print-sheet proposal modern-proposal" style="--qa:${esc(s.accent||settings.primaryColor||'#6f2dbd')};--qh:${esc(s.headerBg||'#f3eafd')};--qc:${esc(s.clientColor||'#2f123f')}">${head}${body}<footer>${esc(dynamicText(s.footer||'',tokens))}</footer></div>`}

// Versão final da Pré-Nota com emitente completo e logo opcional
function invoicePrintHtml(i,tpl){const t=tpl||invoiceTemplateFor(),c=i.clientSnapshot||{};const tokens={cliente:c.company||c.name||clientName(i.clientId),numero_pre_nota:i.number,vendedor:i.salesperson||'',data:dmy(i.createdAt),total:brl(i.total),prazo:dmy(i.deliveryDeadline),empresa:settings.companyName||'Toca dos Brindes'};const issuer=[settings.companyLegalName||settings.companyName,settings.companyDocument?`CNPJ ${settings.companyDocument}`:'',settings.companyIE?`I.E. ${settings.companyIE}`:'',settings.companyAddress,[settings.companyCity,settings.companyState].filter(Boolean).join('/'),settings.companyZipCode?`CEP ${settings.companyZipCode}`:'',settings.companyPhone,settings.companyEmail].filter(Boolean);const logo=t.showLogo===false?'':(settings.companyLogo?`<img src="${settings.companyLogo}" class="prenote-logo">`:'');return `<div class="print-sheet internal-doc formal-prenote" style="--ia:${esc(t.accent||'#394150')}"><div class="doc-warning">${esc(t.warningText||'DOCUMENTO INTERNO • SEM VALOR FISCAL')}</div><div class="doc-grid prenote-head"><div>${t.showCompany!==false?`${logo}<b>EMITENTE</b><h2>${esc(settings.companyName||'Toca dos Brindes')}</h2><small>${issuer.map(esc).join('<br>')}</small>`:''}</div><div><b>CONTROLE</b><h2>${esc(i.number||'PRÉVIA')}</h2><small>Emissão: ${dmy(i.createdAt)}</small>${i.orderId?`<br><small>Pedido: ${esc(cache.orders.find(o=>o.id===Number(i.orderId))?.number||String(i.orderId))}</small>`:''}${i.quoteId?`<br><small>Orçamento: ${esc(cache.quotes.find(q=>q.id===Number(i.quoteId))?.number||String(i.quoteId))}</small>`:''}</div></div><div class="doc-block"><b>DESTINATÁRIO</b><div class="doc-grid"><span><small>Razão social / Nome</small><strong>${esc(tokens.cliente)}</strong></span>${t.showDocument!==false?`<span><small>CNPJ/CPF</small><strong>${esc(c.document||'—')}</strong></span>`:''}<span><small>Inscrição Estadual</small><strong>${esc(c.ie||'—')}</strong></span>${t.showPhone!==false?`<span><small>Telefone</small><strong>${esc(c.phone||'—')}</strong></span>`:''}${t.showEmail!==false?`<span><small>E-mail</small><strong>${esc(c.email||'—')}</strong></span>`:''}<span><small>Endereço completo</small><strong>${esc([c.address,c.addressNumber,c.district,c.city,c.state,c.zipCode].filter(Boolean).join(', ')||'—')}</strong></span>${t.showSeller!==false?`<span><small>Vendedor</small><strong>${esc(i.salesperson||'—')}</strong></span>`:''}</div></div><div class="doc-block"><b>NATUREZA / FINALIDADE</b><p>${esc(i.nature||'Pré-Nota comercial interna')}</p></div><table class="print-table fiscal-table"><thead><tr><th>Cód.</th><th>Descrição</th><th>Qtd.</th><th>V. Unit.</th><th>V. Total</th></tr></thead><tbody>${(i.items||[]).map(x=>`<tr><td>${esc(x.code||x.supplierCode||x.librarySnapshot?.internalCode||'—')}</td><td>${esc(x.productName||x.description||'Item')}</td><td>${Number(x.qty)||0}</td><td>${brl(x.unitPrice)}</td><td>${brl(x.grossTotal||Number(x.qty||0)*Number(x.unitPrice||0))}</td></tr>`).join('')}</tbody></table><div class="formal-totals"><span>Subtotal <b>${brl(i.subtotal??(i.items||[]).reduce((s,x)=>s+Number(x.grossTotal||0),0))}</b></span><span>Frete <b>${brl(i.freight)}</b></span><span>Impostos / Acréscimos <b>${brl(i.taxes)}</b></span><span>Desconto <b>${brl(i.discount)}</b></span></div><div class="doc-total"><span>VALOR TOTAL DA PRÉ-NOTA</span><b>${brl(i.total)}</b></div>${t.showPayment!==false?`<div class="doc-block"><b>CONDIÇÕES DE PAGAMENTO</b><p>${esc(i.paymentData||'—')}</p><small>Vencimento: ${dmy(i.paymentDueDate)}</small></div>`:''}${t.showDelivery!==false?`<div class="doc-block"><b>ENTREGA</b><p>Prazo: ${dmy(i.deliveryDeadline)} · ${esc(i.deliveryAddress||'Endereço conforme cadastro do cliente')}</p></div>`:''}<div class="doc-block"><b>INFORMAÇÕES COMPLEMENTARES</b><p>${esc(i.notes||'—')}</p></div><div class="legal-note">${esc(dynamicText(t.footer||'',tokens))}</div></div>`}

async function endSession(prefix){if(!await C4UDialog.confirm('Encerrar esta sessão?'))return;await api('/api/sessions/'+encodeURIComponent(prefix)+'/end',{method:'POST',body:'{}'});toast('Sessão encerrada');refreshPresencePanel()}


